// Initialize the global container if it doesn't exist yet
window.CourseQuestions = window.CourseQuestions || {};

// Assign this course's questions array directly
window.CourseQuestions["pau-fmm-291"] = [
  { q: "A multimedia production company is preparing a feasibility report on adopting an artificial-intelligence editing platform. Which structure and reasoning best satisfy the requirements of a professional business report?", o: ["Include raw interview transcripts, subjective personal opinions, and a series of recommendations that are entirely unrelated to the data and findings presented in the report.", "Begin with promotional claims, omit methodology, and conclude that the project is feasible because it appears innovative", "Define the purpose and scope, explain the methodology, present evidence-based findings, draw data-limited conclusions, and provide specific action-oriented recommendations", "Focus exclusively on technical features and place the decision and recommendations before the analysis"], a: 2, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A film studio must reject a director’s request for additional production funding while preserving the professional relationship. Which communication strategy is most appropriate?", o: ["Hide the refusal in vague language, blame the director personally, and avoid offering any alternative", "Use a tactful indirect structure: acknowledge the proposal, explain the decision with relevant reasons, state the refusal clearly, and offer a constructive alternative or goodwill closing", "Offer an emotional apology, disclose confidential budget details to justify the decision, and promise that the request will be approved at a later date to maintain the director's enthusiasm.", "Announce the refusal in the opening sentence, provide no explanation, and end with a warning about future applications"], a: 1, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "During a final-year project presentation about representation in Nigerian cinema, which approach demonstrates the strongest application of effective oral-presentation principles?", o: ["Begin without context, present unrelated examples, and allow questions to replace the planned argument", "Include every research detail on the slides, read each sentence aloud to ensure accuracy, and omit the conclusion to maximize the amount of content presented to the audience", "Analyse the audience, state a clear purpose, organize a focused introduction-body-conclusion structure, use relevant visuals, rehearse delivery, and reserve time for questions", "Use highly technical terminology, avoid audience interaction, and rely on visual effects rather than evidence"], a: 2, h: "Keep the audience and purpose in view, organize the message clearly, and support key points with relevant evidence." },
  { q: "A multimedia producer is writing an email to a post-production team about a delayed delivery that affects a broadcast deadline. Which revision best follows professional Business English principles?", o: ["Begin with lengthy background information, use informal slang, and leave the recipient to infer the deadline", "Use a precise subject line, state the main point immediately, explain the impact briefly, specify required actions and deadlines, and close professionally", "Use an urgent subject line in capital letters, include every previous email, and assign blame before stating the requested action", "Copy every department, attach unrelated files, and use phrases like “Please kindly revert back at your earliest convenience” to delay the actual decision."], a: 1, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "In a production meeting involving Nigerian, Norwegian, and Japanese partners, a participant remains silent after a proposal. What is the most professionally appropriate interpretation and response?", o: ["Treat the silence as definite approval and record the proposal as an agreed decision", "Interpret the silence as hostility and challenge the participant publicly", "Avoid assuming agreement or disagreement; politely check understanding, invite the participant’s view, and adapt the discussion to possible cultural differences in silence and turn-taking", "Continue speaking immediately to maintain the momentum of the meeting, as silence in a professional setting typically indicates that the participant has no relevant contribution to make."], a: 2, h: "Aim for respectful participation, clarification, objective discussion, and a clearly recorded outcome." },
  { q: "A documentary producer wants to request permission from a television station to use archival footage. Which sentence best combines formal register, precise purpose, and appropriate business-letter structure?", o: ["We need the clips immediately, so please send them without asking unnecessary questions.", "I am writing to request permission to use the archival footage identified in the attached list for our documentary, Voices of the Coast.", "We would be very grateful if you could kindly review our request and provide a formal response regarding the usage rights at your earliest convenience.", "I want you to allow us to use those old videos because they will make our film better."], a: 1, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "A post-production supervisor writes: “The editor completed the colour correction, exported the master file, and the subtitles were uploaded.” Which revision best demonstrates grammatical parallelism and active voice?", o: ["The colour correction was completed, exported, and the editor uploaded the subtitles.", "The editor completed the colour correction, exported the master file, and uploaded the subtitles.", "The editor was completing the colour correction, exporting the master file, and the subtitles uploaded.", "The editor completed the colour correction, the master file was exported, and uploaded the subtitles."], a: 1, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A multimedia company has surveyed 120 viewers about the accessibility of its streaming platform. Which passage is most suitable for the findings section of a formal business report?", o: ["Viewers will probably prefer a new interface because accessibility is always the most important feature.", "The majority of respondents expressed significant frustration with the current subtitle system, suggesting that the platform requires a complete redesign.", "Of the 120 respondents, 78 reported difficulty locating subtitles; this finding indicates a need to improve the platform’s accessibility controls.", "The survey was interesting, and we recommend several improvements before presenting any results."], a: 2, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A Nigerian filmmaker is negotiating international distribution rights with a European streaming company. Which statement best applies principled negotiation and professional intercultural communication?", o: ["We will disclose our minimum acceptable fee immediately to ensure the negotiation proceeds efficiently and to avoid any unnecessary delays in the process.", "Your company should accept our terms because Nigerian production carries greater cultural importance.", "Our opening offer is final, and discussing your interests would weaken our bargaining position.", "We value the proposed release schedule; could we compare our underlying priorities and develop a revenue-sharing option that benefits both parties?"], a: 3, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "A film student is preparing a presentation on the commercial impact of short-form video. Which opening best applies audience awareness, an initial benefit promise, and an engaging presentation strategy?", o: ["By the end of this presentation, you will be able to identify three ways short-form video can increase audience reach while reducing promotional costs.", "While short-form video is popular, it is unnecessary to explain its importance or provide evidence because the audience already understands its commercial impact.", "I have many slides and statistics, although the audience may not understand how they relate to film production.", "My topic is short-form video, and I will read every definition before discussing its relevance to your work."], a: 0, h: "Keep the audience and purpose in view, organize the message clearly, and support key points with relevant evidence." },
  { q: "A Nigerian multimedia company receives an English email from a foreign client stating, “The revised storyboard is not quite what we had in mind.” As project coordinator, which response best demonstrates strategic competence, intercultural sensitivity, and professional email practice?", o: ["Interpret the statement as a final rejection of the work and immediately cancel the project without seeking further discussion or clarification from the client.", "Thank the client for the feedback, paraphrase the concern, ask targeted clarification questions, and propose a deadline for submitting a revised storyboard", "Reply only, “Noted,” because requesting clarification could appear unprofessional", "Defend the storyboard immediately and explain that the client’s expectations were unclear"], a: 1, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "Translate the following Nigerian business-English message into the most appropriate formal English: “I am writing to inform you that the location scout has been shifted to Friday because the equipment has not arrived.”", o: ["I am informing you that the location scout is shifting Friday due to equipment delayness.", "I write to tell you that the location scouting was moved on Friday since the equipment did not come.", "I am writing to inform you that the location scout has shifted itself to Friday because the equipment is not arriving.", "I am writing to inform you that the location scout has been rescheduled for Friday because the equipment has not arrived."], a: 3, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "Complete the sentence with the grammatically and semantically appropriate verb forms for a production report: “By the time the client reviewed the rough cut, the editor  the transitions and  the revised file to the shared drive.”", o: ["was correcting; had upload", "corrected; has uploaded", "had corrected; had uploaded", "has corrected; uploaded"], a: 2, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A final-year student is writing a report on audience responses to a virtual-reality documentary. Which sentence uses cautious academic diction, appropriate tense, and evidence-based interpretation?", o: ["Immersive sound definitely transformed the documentary into an objectively superior work for all viewers.", "The questionnaire results suggest that immersive sound increased viewers’ emotional engagement, although the sample size limits the generalisability of this finding.", "The questionnaire results prove that immersive sound always produces emotional engagement in every audience.", "The results are suggesting that immersive sound will have increased emotional engagement because the participants obviously liked the experience during the study."], a: 1, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A production manager must write minutes for a meeting in which the team discussed a delayed release but reached no decision. Which entry follows the conventions of professional minutes?", o: ["The team discussed the delayed release; no decision was taken, and the matter was deferred to the next meeting.", "The production manager felt that the marketing team caused the delay.", "The team discussed the delayed release and probably agreed to solve it soon.", "The team members expressed various opinions regarding the release delay, but no consensus was reached during the session."], a: 0, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "A film-production company has completed a survey of 150 viewers about its proposed streaming platform. Which sentence is grammatically correct and appropriately cautious for the report’s findings section?", o: ["The results indicates that 92 respondents prefers subtitles, although the sample may not represents the entire target audience.", "The results indicate that 92 respondents prefer subtitles, although the sample may not represent the entire target audience.", "The results are indicating that 92 respondents prefer subtitles, although the sample may not representing the entire target audience.", "The results indicated that 92 respondents prefers subtitles, although the sample may not represented the entire target audience."], a: 1, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "Translate the following formal business instruction into the most accurate and professional Nigerian English: “Please submit the revised production schedule by 4 p.m. on Friday so that the distribution team can update the release plan.”", o: ["You are requested to submit the revised production schedule on Friday, so the distribution team will update the release plan before then.", "Please submit the revised production schedule by 4 p.m. on Friday so that the distribution team can update the release plan.", "Kindly submit the revised production schedule on Friday at 4 p.m. in order for the distribution team to be updating the release plan.", "Please submit the revised production schedule by Friday 4 p.m., whereby the distribution team can updated the release plan."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A director is writing a formal complaint to a post-production vendor about defective audio files. Which sentence uses the appropriate tense, preposition, and formal vocabulary?", o: ["We have received the files at 12 October and identified several defects on the dialogue tracks.", "We had received the files in 12 October and identified several defects into the dialogue tracks.", "We received the files at 12 October and have identified several defects at the dialogue tracks.", "We received the files on 12 October and identified several defects in the dialogue tracks."], a: 3, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A film researcher wants to integrate a source into an argument without plagiarising it. The source states: “Streaming platforms have altered audience expectations by making on-demand access a normal feature of media consumption.” Which option is the best academically responsible paraphrase?", o: ["According to the source, streaming platforms are harmful because they force audiences to consume media whenever they want (Author, Year).", "The normalisation of on-demand viewing through streaming services has changed what audiences expect from media access (Author, Year).", "Streaming platforms have changed audience expectations, and this proves that all viewers now reject scheduled broadcasting (Author, Year).", "Streaming platforms have altered audience expectations by making on-demand access a normal feature of media consumption (Author, Year)."], a: 1, h: "Preserve the source’s meaning in your own wording and acknowledge the source; do not add claims it does not make." },
  { q: "A multimedia project manager is preparing an email to a cinematographer who has missed a delivery deadline. Which closing best maintains a professional tone while making the required future action clear?", o: ["Please send the completed footage by 10 a.m. tomorrow and confirm once the upload is complete. Kind regards,", "Send the footage now!!! Thanks.", "You must send the footage immediately to avoid serious project consequences. Please confirm receipt. Yours,", "I hope you will eventually send the footage whenever you are ready. Best,"], a: 0, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "You are preparing an internal memo after a production meeting. The team discussed three options, selected one, assigned it to the logistics officer, and set a deadline for 18 November. Which wording records the outcome most accurately and objectively?", o: ["The logistics officer was held responsible for the delay in the previous production cycle.", "The team selected Option Two; the logistics officer will implement it by 18 November.", "Everyone agreed that Option Two was obviously the best choice.", "Option Two may perhaps be implemented sometime in November."], a: 1, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "You are translating a Nigerian production update into formal international English: “The client don approve the final cut, but make we wait for the legal clearance before release.” Which translation is most accurate?", o: ["The client approved the final cut, but we are waiting legal clearance before releasing.", "The client has approved the final cut, but we should await legal clearance before release.", "The client has approve the final cut, but let us wait on legal clearance for release.", "The client has approved the final cut, although legal clearance was waited before release."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are reviewing a proposal that claims, “Because two viewers complained about the subtitles, the entire audience rejects the platform.” Which critical revision identifies the reasoning error and improves the language?", o: ["The claim is a false cause; therefore, the entire audience probably supports the platform.", "The claim is circular reasoning; therefore, the complaints should be removed from the report.", "The claim is a hasty generalisation; the evidence does not represent the entire audience.", "The claim is an appeal to authority; therefore, two complaints are sufficient evidence."], a: 2, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "You are writing a formal letter to a company whose recipient’s name is unknown. Which opening and closing combination follows standard business-correspondence conventions?", o: ["Dear Sir or Madam; Yours faithfully", "Dear Sir or Madam; Yours sincerely", "Dear Recruiter; Yours sincerely", "To Whom It May Concern; Best wishes"], a: 0, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "You are editing this sentence in a feasibility report: “The new editing suite is more cheaper, more faster, and more easier to maintain than the existing suite.” Which revision is grammatically correct and professionally concise?", o: ["The new editing suite is cheaper, faster, and easier to maintain than the existing suite.", "The new editing suite is cheapest, more fast, and easier maintaining than the existing suite.", "The new editing suite is more cheaper, faster, and more easy to maintain than the existing suite.", "The new editing suite is more cheaply, more quickly, and more easily maintained than the existing suite."], a: 0, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are preparing an executive summary after investigating repeated delays in a film’s post-production. Your interviews show that unclear approval procedures, rather than staff shortages, caused most delays. Which sentence reports the finding most accurately?", o: ["The interviews show that the production team failed because it lacked commitment.", "The interviews suggest that unclear procedures and staff shortages are equally responsible.", "The interviews prove that staff shortages have no impact on the post-production schedules of any film projects.", "The interviews indicate that unclear approval procedures contributed more to the delays than staff shortages."], a: 3, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are translating a Nigerian producer’s message for an international investor: “We don finish the rough cut, but the sound designer never send the final mix.” Which translation is grammatically and professionally correct?", o: ["We have completed the rough cut, but the sound designer has not sent the final mix.", "We have finish the rough cut, but the sound designer has not send the final mix.", "We finished the rough cut, but the sound designer did not sent the final mix.", "We had completed the rough cut, but the sound designer never sends the final mix."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are drafting a recommendation after finding that clients often miss online production briefings because invitations contain unclear time-zone information. Which recommendation is most specific and action-oriented?", o: ["Enhance all future communication protocols to minimize client confusion and scheduling errors.", "The company should recognise that international meetings can be difficult.", "Consider perhaps making invitations more accessible to clients.", "State the time zone clearly in every invitation and include an automatic calendar link."], a: 3, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are editing a colleague’s sentence in a report: “The marketing team recommended to postpone the launch because the campaign had not reached enough viewers.” Which revision uses correct verb complementation?", o: ["The marketing team recommended postpone the launch because the campaign had not reaching enough viewers.", "The marketing team recommended that postponing the launch because the campaign has not reach enough viewers.", "The marketing team recommended to postponing the launch because the campaign did not reached enough viewers.", "The marketing team recommended postponing the launch because the campaign had not reached enough viewers."], a: 3, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are chairing a tense meeting about a documentary budget. One participant interrupts another and dismisses her proposal without explanation. Which response best protects productive dialogue while maintaining professional politeness?", o: ["Stop the discussion and instruct the participant to accept the proposal.", "Let her complete the proposal, then address its financial implications using specific evidence.", "Permit the interruption to save time, as rapid disagreement is often more efficient than long explanations.", "Reject the proposal immediately to prevent the meeting from becoming emotional."], a: 1, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are preparing a formal report after interviewing employees about a new remote-editing policy. One respondent says, “The policy has improved collaboration, but unstable internet still affects delivery.” Which sentence integrates this evidence most accurately?", o: ["One respondent reported that the policy had improved collaboration, because unstable internet had improved delivery.", "One respondent reports that the policy improves collaboration, although unstable internet has affected delivery.", "One respondent reported that the policy had improved collaboration, although unstable internet still affected delivery.", "One respondent reported that the policy was improving collaboration, although unstable internet affects delivery."], a: 2, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "You are translating a project manager’s message into formal English: “Abeg, send the revised budget make we fit discuss am with the client tomorrow.” Which version is most appropriate?", o: ["Kindly send the revised budget so we will be able discussing it with the client tomorrow.", "Please send the revised budget so that we can discuss it with the client tomorrow.", "Please send the revised budget because we discussed it with the client tomorrow.", "Send the revised budget, so the client can discuss us tomorrow."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are reviewing a proposal that states, “The pilot film attracted 500 online views; therefore, the full series will certainly become a commercial success.” What is the most defensible revision?", o: ["The pilot’s view count demonstrates that every potential viewer will purchase the series, ensuring a massive profit margin.", "The pilot’s view count is irrelevant because online audiences never predict market performance.", "The pilot’s view count proves that the full series will become a commercial success.", "The pilot’s view count suggests potential interest, but further market evidence is needed to assess commercial success."], a: 3, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "You are writing a polite email to a client whose requested changes cannot be completed before tomorrow’s broadcast. Which sentence uses an appropriate modal verb and professional tone?", o: ["We should have completed the changes, so the delay is entirely your responsibility.", "We cannot complete the changes in time, so you will need to accept the delay for the upcoming broadcast.", "We may not finish the changes, but perhaps the broadcast can be cancelled.", "We will need an additional two working days to complete the requested changes to the required standard."], a: 3, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are editing a business letter about damaged filming equipment. Which sentence uses the correct preposition and formal collocation?", o: ["We are writing for complaining about damage on the camera equipment delivered in Monday.", "We are writing to complain on the damage of the camera equipment delivered at Monday.", "We are writing to complain about the damages into camera equipment delivered by Monday.", "We are writing to complain about the damage to the camera equipment delivered on Monday."], a: 3, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are preparing a trip report after visiting two potential distribution partners. One partner offered technical support; the other offered a larger fee but no marketing assistance. Which sentence presents the comparison objectively and uses parallel structure?", o: ["Partner One offered technical support, whereas Partner Two had a larger fee without being assisted by marketing.", "Partner One offered technical support, whereas Partner Two offered a higher fee but no marketing assistance.", "Partner One offered support, but Partner Two offered more money, proving that Partner Two was the better partner.", "Partner One was more supportive, while Partner Two was financially better and not marketing."], a: 1, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are translating a producer’s message into formal English: “If the broadcaster approves the trailer today, we go release am tomorrow.” Which sentence correctly expresses the conditional meaning?", o: ["If the broadcaster will approve the trailer today, we release it tomorrow.", "If the broadcaster approved the trailer today, we released it tomorrow.", "If the broadcaster approves the trailer today, we will release it tomorrow.", "If the broadcaster approves the trailer today, we would release it tomorrow."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are writing an appraisal report for an assistant editor whose work is accurate but consistently late. Which sentence is specific, balanced, and professionally phrased?", o: ["The assistant editor is excellent but sometimes has a bad attitude about completing work.", "The assistant editor delivers accurate cuts but should improve time management to meet agreed deadlines.", "The assistant editor’s performance is acceptable, although improvement is needed in several unspecified areas.", "The assistant editor is slow, careless, and unsuitable for demanding production work."], a: 1, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are checking a research report that includes this sentence: “The questionnaire was distributed to 80 students, and 64 responses were returned.” Which revision uses appropriate passive construction and avoids ambiguity?", o: ["The questionnaire was distributing to 80 students, and 64 responses had received.", "The questionnaire was distributed by 80 students, and 64 responses were returned them.", "The questionnaire was distributed to 80 students, and 64 completed responses were received.", "The questionnaire distributed 80 students, and 64 responses returned themselves."], a: 2, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are responding to a client who asks whether a revised contract has been signed. The contract has not yet been signed, but the legal team is reviewing it. Which reply is accurate and professionally tactful?", o: ["The contract is being signed by the legal team and will be confirmed shortly.", "The contract has not been signed because the legal team is delaying the project.", "The contract was under review, so it should already have been signed.", "The contract is currently under legal review; we will confirm once it has been signed."], a: 3, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "Translate into formal business English: “The client don approve the concept, but e request make we reduce the production cost.”", o: ["The client approved the concept but requested us reducing the production cost.", "The client had approved the concept but is requesting to reduce the production cost.", "The client has approve the concept and requested that we reduced production costs.", "The client has approved the concept but has requested a reduction in production costs."], a: 3, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "Which sentence most accurately distinguishes a report’s conclusion from its recommendation?", o: ["The findings indicate that unclear approvals caused delays; the company should introduce a documented approval workflow.", "Unclear approvals caused delays, so the company will probably introduce a documented approval workflow.", "The report concludes that the company should introduce a documented approval workflow to prevent future delays.", "The company should introduce a documented approval workflow because unclear approvals caused delays."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A client writes: “Your proposal is interesting, but it does not address our concern about audience retention.” Which response best demonstrates strategic competence?", o: ["We understand your concern and will revise the proposal to improve all elements that you find unsatisfactory to ensure we meet your expectations.", "Your concern is unclear because audience retention depends entirely on viewer preference.", "Thank you, but our proposal already addresses audience retention through its innovative concept.", "Thank you for identifying that concern; could you clarify which audience segment and retention period we should address in the revision?"], a: 3, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "Choose the grammatically correct version for an appraisal report: “Although the coordinator meet most targets, she fail to submit two reports on time.”", o: ["Although the coordinator had meet most targets, she failed submit two reports on time.", "Although the coordinator met most targets, she failed to submit two reports on time.", "Although the coordinator met most targets, she has failed submitting two reports on time.", "Although the coordinator has met most targets, she fail to submit two reports on time."], a: 1, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A research report claims: “The interviewees preferred the new platform because all young people prefer digital communication.” Which revision is most academically defensible?", o: ["The interviews establish that digital communication is preferable whenever participants are young.", "The interviews prove that young people universally prefer digital communication.", "The interview data cannot support a broad conclusion because the participants' subjective preferences do not represent the entire demographic.", "The interviews suggest that these participants preferred the new platform; broader research is needed before generalising to all young people."], a: 3, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Translate into formal English: “The client talk say make we shift the launch because the advert never ready.”", o: ["The client suggested postponing the launch because the advertisement was not ready.", "The client talked that we shift the launch because the advertisement never was ready.", "The client said we should shifted the launch because the advert has not ready.", "The client requested that we postponed the launch because the advert is not yet ready."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "Choose the best revision for a report sentence: “The survey results shows that most viewers prefers shorter trailers, but the sample size limit the conclusion.”", o: ["The survey results are showing that most viewers are preferring shorter trailers, but the sample size is limiting conclusions.", "The survey results showed that most viewers preferred shorter trailers, but the sample size limited the conclusions.", "The survey result shows that most viewers prefers shorter trailers, but the sample size limit the conclusion.", "The survey results show that most viewers prefer shorter trailers, but the sample size limits the conclusion."], a: 3, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A report finds that poor internet connectivity delayed online editing sessions, but it also notes that only 12 of 100 participants experienced serious disruption. Which conclusion is most defensible?", o: ["Connectivity was the primary cause of delay, as any reported disruption is enough to invalidate the entire editing workflow.", "Connectivity affected everyone indirectly, so the report should attribute all delays to internet access.", "Connectivity had no meaningful effect because most participants reported no serious disruption.", "Connectivity affected a minority of participants and should be addressed without being presented as the sole cause of delay."], a: 3, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Choose the most appropriate indirect refusal to a client requesting delivery within two days when the verified production schedule requires five days.", o: ["Your request cannot be accepted, although perhaps the team might finish earlier if everything goes well.", "To meet the required quality standards, we would need five working days; we can deliver a preview within two days.", "We cannot deliver in two days because the schedule is impossible and your request is unrealistic.", "We regret to inform you that a two-day delivery is not possible; we are unable to offer any alternative at this time."], a: 1, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "A negotiation partner says, “Your price is too high,” without explaining the concern. Which response best applies active listening and interest-based negotiation?", o: ["If the price is too high, you should choose another production company.", "Could you clarify whether the concern relates to the total budget, payment schedule, or expected deliverables?", "Our price is justified, and reducing it would weaken our position.", "We can offer an immediate discount on the total price, provided that the scope of the deliverables remains unchanged."], a: 1, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "Translate into formal business English: “We don receive the footage, but the audio files never complete.”", o: ["We have received the footage, but the audio files are incomplete.", "We received the footage, although the audio files never completed themselves.", "We have receive the footage, but the audio files were not complete.", "We received the footage, but the audio files have not completed."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "Choose the grammatically correct sentence for a production update.", o: ["If the client approves the revised script today, the crew will begin filming on Monday.", "If the client will approve the revised script today, the crew begins filming on Monday.", "If the client approved the revised script today, the crew will began filming on Monday.", "If the client approves the revised script today, the crew would begin filming on Monday."], a: 0, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A report finds that 72% of respondents support online submission, while 18% prefer physical copies and 10% are undecided. Which conclusion is most logically justified?", o: ["Online submission is the leading preference, but the minority preferences should inform the implementation plan.", "Physical copies remain equally important because 28% did not choose online submission.", "The presence of undecided respondents makes it impossible to draw a valid comparison between the two submission methods.", "Online submission is universally preferred and should immediately replace physical copies."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A client rejects a proposal because its budget exceeds the approved limit. Which response best combines tact, clarity, and a future-oriented alternative?", o: ["We can reduce the budget by removing essential elements, although the final result may be unsatisfactory.", "The proposal cannot be changed because its current scope reflects the project’s actual requirements.", "We regret the rejection, though we suggest increasing the budget to ensure the project maintains its intended quality and standards.", "We understand the budget constraint; we can revise the scope or propose a phased production plan within the approved limit."], a: 3, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "Complete the sentence with the most appropriate academic vocabulary: “Although the sample was limited, the findings provide ___ evidence that audience engagement increased after the platform redesign.”", o: ["universal", "preliminary", "indisputable", "absolute"], a: 1, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "Translate into formal English: “The client no fit attend the meeting today, so make we reschedule am for Thursday.”", o: ["The client cannot attend today’s meeting, so let us reschedule it for Thursday.", "The client did not attend the meeting today, so we will reschedule it by Thursday.", "The client is not fitting to attend today, so let us shift the meeting at Thursday.", "The client cannot attends the meeting today, so we rescheduled it on Thursday."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A report finds that a new editing workflow reduced average turnaround time from ten days to seven, but the study examined only one project. Which conclusion is most defensible?", o: ["The workflow reduced turnaround time in this project, but further evidence is needed before generalising.", "The workflow cannot be evaluated because a single project provides insufficient evidence for a valid assessment.", "The workflow will reduce turnaround time in every future project.", "The workflow reduced turnaround time by exactly 30% across the organisation."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Complete the sentence appropriately: “The production manager recommended that the team  the release until legal clearance  obtained.”", o: ["to postpone; will be", "postponed; was", "postponing; has been", "postpone; is"], a: 3, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A client says, “Your proposal is attractive, but the delivery schedule is unrealistic.” Which reply best uses clarification and interest-based negotiation?", o: ["Which milestone creates the greatest concern, and would a phased delivery address it?", "The schedule is realistic because our team has used it before.", "The schedule is fixed, so the proposal cannot be reconsidered.", "We can shorten the schedule if you accept responsibility for any resulting defects."], a: 0, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "Which sentence best integrates a source into an academic argument without presenting the source’s wording as the writer’s own?", o: ["“Clear approval procedures shorten production delays” (Okafor, 2024), with no quotation marks or explanation.", "Recent research links clear approval procedures with shorter production delays (Okafor, 2024), supporting the need for a documented workflow.", "Okafor (2024) proves that documented workflows eliminate every possible production delay.", "Clear approval procedures shorten production delays, and this statement is considered common knowledge and therefore requires no formal citation."], a: 1, h: "Keep the audience and purpose in view, organize the message clearly, and support key points with relevant evidence." },
  { q: "A final-year multimedia student is translating this Nigerian production update for an international commissioning editor: “We don complete the first assembly, but the client never send the clearance documents, so we no fit publish the trailer.” Which version preserves the aspect, causality, and professional register most accurately?", o: ["We completed the first assembly, but the client did not send the clearance documents, so we could not publish the trailer.", "We have completed the first assembly, but the client has not sent the clearance documents, so we cannot publish the trailer.", "We have complete the first assembly, but the client has not send the clearance documents, so we cannot published the trailer.", "We had completed the first assembly, although the client never sent the clearance documents; therefore, we should publish the trailer."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A research report states: “The platform was redesigned after users complained about navigation. Following the redesign, average task-completion time fell from six minutes to four.” Which sentence provides the most academically responsible interpretation?", o: ["The redesign caused the reduction because the two events occurred in chronological order.", "The redesign had no possible effect because user complaints preceded it.", "The reduction proves that every user found the redesigned platform easier to navigate, confirming the redesign's total success.", "The reduction followed the redesign, but the evidence does not by itself establish that the redesign caused the improvement."], a: 3, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A film company wants to reject a proposed delivery date without damaging its relationship with a streaming partner. Which sentence best uses an indirect negative-message strategy while remaining clear and action-oriented?", o: ["To complete the required sound mix and quality checks, we propose delivering the master on 18 June rather than 12 June.", "The master will probably not be ready on 12 June, although the team may try to deliver it.", "We cannot meet 12 June, and the streaming partner should revise its expectations.", "We regret that the deadline is impossible because the post-production department has failed to plan properly."], a: 0, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "A final-year student is editing this sentence in a feasibility report: “The proposed virtual-production studio will reduce location costs, improve scheduling flexibility, and it can support real-time collaboration.” Which revision best demonstrates parallel structure and concise professional style?", o: ["The proposed virtual-production studio will reduce location costs, improve scheduling flexibility, and support real-time collaboration.", "The proposed virtual-production studio will reduce location costs, will improve scheduling flexibility, and it can be supporting real-time collaboration.", "The proposed virtual-production studio reduces location costs, improved scheduling flexibility, and supports real-time collaboration.", "The proposed virtual-production studio will reduce location costs, improving scheduling flexibility, and it can support real-time collaboration."], a: 0, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "During a negotiation over documentary distribution, the distributor says, “We need exclusive rights in all territories, but we cannot increase the licence fee.” Which response best applies interest-based negotiation and protects the producer’s bargaining position?", o: ["We reject the proposal and immediately disclose our minimum acceptable fee to demonstrate transparency and ensure we do not waste time on unviable commercial terms.", "We insist on non-exclusive rights everywhere and refuse to discuss the distributor’s commercial interests.", "We accept worldwide exclusivity at the current fee because maintaining the relationship is more important than the contract terms.", "Could we identify the territories and duration you require, then explore limited exclusivity in exchange for a higher fee or defined performance commitments?"], a: 3, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "A Nigerian documentary producer is translating a post-production memo for an international broadcaster: “We don finish the offline edit, but the legal team never clear the music, so the trailer no fit go live.” Which version accurately preserves the tense, contrast, and cause-and-effect relationship?", o: ["We have complete the offline edit, but the legal team has not clear the music, so the trailer cannot goes live.", "We had completed the offline edit, but the legal team was clearing the music; therefore, the trailer should go live.", "We have completed the offline edit, but the legal team has not cleared the music, so the trailer cannot go live.", "We completed the offline edit, although the legal team cleared the music, so the trailer can go live."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A final-year student is writing a report on the effect of virtual production on location planning. The study used interviews with eight production managers and found that virtual production reduced travel for some projects but increased pre-production demands. Which sentence best represents the evidence without overgeneralising?", o: ["Interviews suggest that virtual production may reduce travel in some projects while increasing pre-production demands; the limited sample restricts wider generalisation.", "Based on the interviews, eight production managers establish that virtual production is the most efficient method for all film productions, regardless of the project scale.", "Virtual production increases pre-production demands, so it cannot provide any logistical benefit.", "Interviews prove that virtual production reduces travel and improves every production workflow."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A streaming platform has rejected a multimedia proposal because the requested budget exceeds its current allocation. Which response best combines an indirect negative-message structure, reader benefit, and a feasible alternative?", o: ["To remain within the current allocation, we propose a reduced first phase, followed by expansion after audience-response data are reviewed.", "We cannot accept the allocation, but perhaps the project might continue if additional funds become available.", "While we cannot approve the full budget at this time, we are unable to move forward with the current proposal due to existing fiscal constraints.", "Your budget is insufficient, and the platform must either increase it or abandon the proposal."], a: 0, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "A student is revising this sentence in a research essay: “The questionnaire data demonstrates that viewers was more engaged by interactive documentaries, which suggest that the format improve audience participation.” Which revision is grammatically correct and academically cautious?", o: ["The questionnaire data demonstrate that viewers were more engaged by interactive documentaries, proving that the format improves participation for all audiences.", "The questionnaire data demonstrates that viewers was more engaged by interactive documentaries, which suggests that the format improves audience participation.", "The questionnaire data demonstrated that viewers is more engaged by interactive documentaries, suggesting that the format must improve audience participation.", "The questionnaire data demonstrate that viewers were more engaged by interactive documentaries, suggesting that the format may improve audience participation."], a: 3, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "During negotiations for a multimedia co-production, a foreign distributor requests worldwide exclusivity for ten years without offering a higher licence fee. Which response best applies BATNA awareness, interest-based negotiation, and precise contractual language?", o: ["We accept the request to preserve the long-term relationship, prioritizing the partnership over the immediate financial value of the exclusivity terms.", "We can explore limited exclusivity by territory and duration, provided that the fee and minimum promotional commitments reflect the rights granted.", "We agree to ten years of exclusivity but rely on a verbal promise that the distributor will promote the project.", "We reject all exclusivity and disclose our minimum fee before discussing the distributor’s underlying interests."], a: 1, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "A final-year film student is revising a research report on audience engagement with interactive documentaries. The study used a questionnaire completed by 240 viewers and follow-up interviews with 12 participants. Which sentence best integrates the two methods, uses appropriate tense, and avoids claiming more than the evidence supports?", o: ["The interviews demonstrated that all questionnaire respondents preferred interactive features, which suggests a strong correlation between the use of interactive elements and the level of engagement reported by the viewers.", "Questionnaire responses indicated higher engagement with interactive features, while interviews suggested that some viewers valued the sense of agency; the findings may not represent all documentary audiences.", "The questionnaire established causation, whereas the interviews merely confirmed the universal result.", "The questionnaire and interviews proved that interactive documentaries increase engagement for every audience."], a: 1, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "Translate into formal English: “The broadcaster don request make we submit the final master before Friday, but the colourist never finish the grade.”", o: ["The broadcaster has request that we submit the final master on Friday, although the colourist has finish the grade.", "The broadcaster requested us to submitted the final master before Friday, but the colourist never finish grading.", "The broadcaster has requested that we submit the final master before Friday, but the colourist has not completed the grade.", "The broadcaster requested that we submitting the final master before Friday, but the colourist did not completed the grade."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A production company is writing a report after finding that an automated captioning system produced errors in names and technical terms. Which recommendation is most specific, future-oriented, and directly linked to the finding?", o: ["Consider perhaps reviewing captions whenever the production schedule permits.", "Require a trained reviewer to verify names and technical terms before every caption file is delivered.", "Conclude that automated captioning technology is entirely unsuitable for all professional-grade productions.", "Improve captioning quality and ensure that errors are reduced in future projects."], a: 1, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A student is writing an academic paragraph about film distribution. Which sentence uses an appropriate reporting verb, citation, and cautious interpretation?", o: ["Adeyemi (2023) argues that platform algorithms influence discoverability, although the study does not establish that they determine audience choice.", "Adeyemi (2023) says algorithms influence discoverability, but the citation is unnecessary because the idea is widely known.", "According to Adeyemi (2023), platform algorithms determine audience choice, which suggests that no further empirical evidence is required for this claim.", "Adeyemi (2023) proves that algorithms determine what every viewer watches."], a: 0, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "During a co-production meeting, a distributor proposes reducing the number of shooting days without explaining the expected savings or creative consequences. Which response best demonstrates professional meeting language, clarification, and interest-based negotiation?", o: ["The distributor should provide a complete alternative plan before any discussion can continue.", "We accept the proposal immediately because fewer shooting days will necessarily reduce the total budget.", "We reject the proposal immediately because reducing the number of shooting days will always damage the overall production quality.", "Could you clarify the projected savings and how the reduction would affect the creative requirements before we evaluate the proposal?"], a: 3, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "A final-year student is translating a production memo into formal English: “The director don approve the revised treatment, but she ask make the research team add more evidence before the pitch.” Which version preserves the tense, reporting structure, and professional register most accurately?", o: ["The director has approved the revised treatment, although she asks the research team to added more evidence before the pitch.", "The director has approve the revised treatment but requested the research team adding more evidence before the pitch.", "The director approved the revised treatment but has asked that the research team added more evidence before the pitch.", "The director has approved the revised treatment but has requested that the research team add more evidence before the pitch."], a: 3, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A student is writing a literature-review paragraph on algorithmic recommendations in streaming media. Which sentence integrates a source responsibly while maintaining grammatical accuracy and avoiding an unsupported causal claim?", o: ["Recommendation algorithms determine viewing choices, so Okoro’s (2024) study requires no further qualification.", "Okoro (2024) reported that algorithms were associated with viewing choices, which proves that the algorithms caused them.", "Okoro (2024) reports an association between recommendation algorithms and viewing choices, but notes that the evidence does not establish direct causation.", "Okoro (2024) asserts that recommendation algorithms are the primary factor that determines exactly what every individual viewer chooses to watch on streaming platforms."], a: 2, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A production company has interviewed editors about a new cloud-based workflow. Most editors praised faster file access, but several reported security concerns. Which sentence would be most appropriate in the findings section of a formal report?", o: ["The findings show that cloud editing should be abandoned despite its operational benefits.", "Editors disliked the workflow because a few participants mentioned security concerns.", "Interviewees valued faster file access, although several raised concerns about data security.", "The interviews prove that cloud editing is superior and completely secure."], a: 2, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A documentary producer is writing to an international broadcaster after discovering that a requested delivery date conflicts with essential legal-clearance procedures. Which sentence best combines tact, precision, and a feasible alternative?", o: ["We regret that delivery is impossible and therefore cannot offer any alternative.", "The master may not be ready, but we will try to send something before the deadline.", "We cannot meet the requested date because the current schedule does not allow for the necessary legal-clearance procedures.", "To complete the required clearance checks, we propose delivering the master on 24 July and providing a review copy on 19 July."], a: 3, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "A student is editing this sentence from a feasibility report: “The proposed virtual-production facility would be economically viable if it attracts enough clients and the company can maintain the equipment.” Which revision best preserves the conditional meaning while improving parallel structure and formal style?", o: ["The proposed virtual-production facility will be economically viable if it attracts sufficient clients and the company can maintaining the equipment.", "The proposed virtual-production facility would be economically viable if it attracted sufficient clients and the company maintained the equipment properly.", "The proposed virtual-production facility would be economically viable if it attracts enough clients and the company maintains the equipment.", "The proposed virtual-production facility is economically viable because it may attract clients and maintain the equipment."], a: 1, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are reviewing a Nigerian producer’s message before sending it to an international broadcaster: “We don submit the budget, but the broadcaster never reply, so we dey wait for confirmation.” Which formal version preserves the meaning and uses appropriate tense?", o: ["We had submitted the budget, but the broadcaster never replied, so we are waiting for a confirmation.", "We submitted the budget, but the broadcaster did not reply, so we waited for confirmation.", "We have submit the budget, but the broadcaster has not replied, so we are waiting confirmation.", "We have submitted the budget, but the broadcaster has not replied, so we are awaiting confirmation."], a: 3, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are writing a research report after observing that four of six production teams adopted a new scheduling tool, while two rejected it because of training demands. Which conclusion is most defensible?", o: ["The tool is suitable for all production teams because most observed teams adopted it.", "Training demands were the only reason teams made different choices.", "The tool was adopted by most observed teams, but training demands may limit wider adoption.", "The tool failed because two teams rejected it."], a: 2, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are negotiating with a distributor who wants exclusive rights but refuses to specify the territories or duration. Which response best protects your interests while inviting a workable agreement?", o: ["Could we define the territories and duration first, then discuss a fee that reflects the rights granted?", "We disclose our minimum fee before clarifying the scope of exclusivity.", "We accept worldwide exclusivity until the distributor decides to end it.", "We reject the request for exclusivity and refuse to discuss any of the distributor's specific requirements."], a: 0, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "You are translating a client’s instruction into formal English: “Make una send the revised proposal before noon tomorrow, because the board meeting don shift.” Which version is most accurate?", o: ["Please send the revised proposal on tomorrow before noon because the board meeting shifted.", "Send the revised proposal before noon tomorrow, although the board meeting has rescheduled.", "Please send the revised proposal before noon tomorrow because the board meeting has been rescheduled.", "You are requested to send the revised proposal before noon tomorrow, since the board meeting has shifted itself."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are editing a report sentence about a pilot streaming project: “The project reduced costs, improved access, and it created new risks for data security.” Which revision best demonstrates parallel structure and precise professional style?", o: ["The project reduced costs, improved access, and it was creating risks for data security.", "The project had reduced costs, improving access, and new risks were created by it.", "The project reduced costs, improved access, and created new data-security risks.", "The project reduced costs, was improving access, and created risks concerning data security."], a: 2, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are preparing a grant application for a documentary about coastal erosion. Your evidence includes interviews with six residents, satellite images, and a government report. Which sentence most responsibly integrates the evidence without overstating the findings?", o: ["The interviews and satellite images indicate increasing erosion in the selected communities, consistent with the government report, although the evidence does not represent every coastal area.", "The satellite images are sufficient to establish the causes of erosion without further investigation.", "The government report confirms that every resident has experienced identical environmental damage.", "The interviews and satellite images provide conclusive proof that erosion is increasing throughout the entire country, regardless of the specific local conditions mentioned in the report."], a: 0, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "You are translating a Nigerian producer’s message for an international partner: “The crew don reach the location, but the rain never allow them start shooting.” Which translation is most accurate?", o: ["The crew reached the location, but the rain did not allowed them to start shooting.", "The crew has arrived at the location, but the rain has prevented them from starting the shoot.", "The crew arrived at the location, although the rain allowed them not to start shooting.", "The crew has reach the location, but the rain has not allow them starting the shoot."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are reviewing a proposal that claims a film-training programme “will eliminate unemployment among young people.” You have only a small pilot study and no long-term employment data. Which revision demonstrates the strongest academic and professional judgment?", o: ["The pilot study is too limited in scope to support such a broad claim regarding the programme's impact on youth unemployment.", "The programme will eliminate unemployment if participants complete the training.", "The programme may improve participants’ employability, but its long-term effect on youth unemployment requires further study.", "The pilot proves that training is the only effective solution to youth unemployment."], a: 2, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "You are chairing a meeting in which two departments disagree about whether to spend more on promotion or post-production quality. Which intervention best moves the discussion from opposing positions toward shared interests?", o: ["We should hold an immediate vote to resolve this conflict before the disagreement escalates and impacts our overall project timeline.", "The department with the larger budget should make the final decision.", "Each department should defend its original position until one side withdraws.", "What outcomes must the campaign achieve, and can we compare options that protect quality while meeting the audience-reach target?"], a: 3, h: "Aim for respectful participation, clarification, objective discussion, and a clearly recorded outcome." },
  { q: "You are editing a formal report about a delayed short film. Choose the sentence that uses accurate tense, precise vocabulary, and a clear logical relationship.", o: ["Although the editor had received the footage, the final cut was delayed because several files were corrupted.", "Because the editor had received the footage, the final cut was delayed although no files were corrupted.", "The editor received the footage, but the final cut was delayed because several files were found to be corrupt.", "Although the editor has received the footage, the final cut delayed because several files had corrupt."], a: 0, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are preparing an executive summary for a media company after reviewing invoices, interviews, and delivery records. The evidence shows that late client approvals, not equipment shortages, caused most delays. Which summary sentence is most accurate and appropriately cautious?", o: ["The evidence suggests that equipment shortages were not the primary driver of delays, though they may have played a minor role in certain instances.", "The interviews establish that every delay resulted from client decisions.", "The records show that client approvals and equipment shortages had identical effects.", "The evidence indicates that late client approvals were the main reported cause of delays, although equipment shortages affected some projects."], a: 3, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are translating a Nigerian producer’s message for an international partner: “The editor don send the second cut, but the director never review am because she dey travel.” Which translation preserves the meaning and tense most accurately?", o: ["The editor has sent the second cut, but the director has not reviewed it because she is travelling.", "The editor had sent the second cut, but the director never reviews it because she travels.", "The editor has send the second cut, but the director did not review it because she travelled.", "The editor sent the second cut, but the director is not reviewing it because she has travelled."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are revising a report after discovering that respondents misunderstood one questionnaire item. How should you present this limitation?", o: ["State that the misunderstanding may have affected responses to that item and interpret the related finding cautiously.", "Treat all responses as invalid, regardless of whether other items were understood.", "Omit the specific item from your final analysis and the report without providing any explanation for the omission.", "Ignore the problem because acknowledging limitations weakens the report."], a: 0, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "You are chairing a meeting in which a senior executive presents an unsupported claim about audience behaviour. You want to challenge it without damaging the relationship. Which response is most effective?", o: ["That claim is incorrect, and we should not proceed with the campaign based on that specific information.", "The claim may be correct, so there is no need to examine its basis.", "Could we identify the evidence for that assumption before using it to guide the campaign decision?", "Since you are senior, we will accept the claim and record it as evidence."], a: 2, h: "Aim for respectful participation, clarification, objective discussion, and a clearly recorded outcome." },
  { q: "You are writing a formal email to a client who has requested an additional edit outside the agreed scope. Which response is clearest, most professional, and future-oriented?", o: ["We can complete the additional edit by Friday after confirming the revised fee and delivery schedule.", "The edit is outside scope; therefore, no further discussion is necessary.", "We cannot do the edit because it was not included, and you should have requested it earlier.", "We may possibly complete the edit if the team has enough time and the client agrees."], a: 0, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "You are preparing a post-production report after discovering that the final export contains inconsistent frame rates. The client needs a clear explanation without unnecessary technical detail. Which sentence is most appropriate?", o: ["The final export contains inconsistent frame rates, so we recommend re-exporting the sequence using the project’s standard settings.", "The final export has inconsistent frame rates, therefore the client must understand that the editor made an unacceptable mistake.", "The final export contains frame-rate inconsistencies, which means the entire project is technically unusable.", "The final export is bad because the frames are somehow moving incorrectly."], a: 0, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "You are translating this formal production update into clear Nigerian business English: “The revised schedule has been approved, but the crew will begin filming only after the location permits have been issued.” Which option is most accurate?", o: ["The revised schedule has been approved, but the crew will begin filming only after the location permits are issued.", "The revised schedule was approved, but the crew will begin filming before the location permits will be issued.", "The revised schedule has approve, but the crew begins filming only after the location permits issued.", "The revised schedule has been approved, although the crew began filming because the permits had not issued."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are reviewing a client’s statement in a documentary proposal: “The interview proves that social media is the reason young people no longer watch television.” Only one interview supports this claim. How should you revise it?", o: ["The interview establishes that television viewing has ended among young people and that social media is the primary cause of this shift.", "The interview proves that social media has replaced television for all young people.", "The interview suggests that social media may influence some young people’s television-viewing habits, but broader evidence is required.", "The interview cannot be used because individual experiences have no value in research."], a: 2, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "You are writing a formal email to a supplier whose late delivery has affected your production schedule. Which sentence is firm, specific, and professionally controlled?", o: ["Send the equipment immediately because your delay has disrupted our entire production schedule and caused significant issues.", "Kindly revert back at your earliest convenience concerning the equipment that has not yet been delivered.", "Please confirm by 3 p.m. today when the outstanding equipment will be delivered and provide an updated delivery schedule.", "We are disappointed that you have failed again, and we expect you to correct this situation somehow."], a: 2, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "You are chairing a meeting where two teams defend incompatible budget proposals. The evidence shows that both proposals could meet the project’s goals if their strongest features were combined. What should you say?", o: ["Let each team defend its original position until senior management makes the decision.", "Let us identify the essential benefits of each proposal and develop a combined option that meets the project goals within the available budget.", "Let us hold an immediate vote to decide which team must abandon its proposal so that we can move forward with a single plan without further delay.", "Let us choose the cheaper proposal because cost is the only objective criterion."], a: 1, h: "Aim for respectful participation, clarification, objective discussion, and a clearly recorded outcome." },
  { q: "A multimedia company commissions a report evaluating whether an interactive documentary project is financially and technically viable. Which structure best satisfies the conventions of a feasibility report?", o: ["Abstract, introduction and scope, methodology, findings, conclusion, recommendations, references, and appendices", "Incident description, injury record, witness statements, medical treatment, and safety warning", "Title, promotional slogan, product description, customer testimonials, and sales discount", "Greeting, personal background, narrative dialogue, emotional reaction, and signature"], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A film production manager must inform a freelance editor that the company cannot approve a requested fee increase, while preserving the professional relationship. Which communication strategy is most appropriate?", o: ["Employ an indirect approach by providing a detailed explanation of the budget constraints and offering a compromise to maintain a positive working rapport.", "Use an indirect approach: begin with appreciation, explain relevant constraints, state the decision tactfully, and close with a constructive alternative", "Send a one-line email containing only “Your request has been denied” to demonstrate managerial authority", "Begin with an accusation that the editor is financially unreasonable, then end the message without explanation"], a: 1, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "In a business report on audience engagement with a streaming documentary, which distinction between conclusions and recommendations is theoretically correct?", o: ["Conclusions provide raw questionnaire responses, whereas recommendations summarize the report’s title and references", "Conclusions interpret the evidence about the existing situation, whereas recommendations propose specific future actions", "Conclusions express the writer’s personal opinion, whereas recommendations reproduce the methodology", "Conclusions list future actions, whereas recommendations introduce new evidence not discussed in the findings"], a: 1, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A final-year Film and Multimedia Studies student is presenting research on the effect of short-form video platforms on documentary storytelling. Which presentation plan best reflects effective business and academic communication?", o: ["Begin with unrelated technical details, avoid rehearsal, use decorative visuals, and allow the presentation to exceed the allotted time", "Present only personal opinions, omit all academic references, and use overly complex terminology to create a false impression of expertise throughout the entire presentation", "Define the purpose and audience, preview a few main points, support claims with clear visuals and evidence, manage time, and conclude with a concise summary and recommendation", "Display dense paragraphs on every slide, read them word for word, and postpone the topic until the question-and-answer session"], a: 2, h: "Keep the audience and purpose in view, organize the message clearly, and support key points with relevant evidence." },
  { q: "A Nigerian production studio is negotiating a co-production agreement with an international streaming company. Which approach best applies the principles of intercultural business communication and integrative negotiation?", o: ["Treat the negotiation as a fixed win–lose contest and use unfamiliar idioms to demonstrate linguistic superiority", "Reveal the studio’s minimum acceptable terms immediately and refuse to discuss cultural or relational expectations", "Research the partner’s communication norms, distinguish interests from positions, listen actively, establish objective criteria, and develop mutually beneficial options", "Prioritize personal rapport over project interests and rely on strategic silence to pressure the partner into making immediate concessions during the negotiation process."], a: 2, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "A film studio wants to reject a distributor’s request for exclusive rights while preserving the possibility of future collaboration. Which wording best applies the indirect approach to negative business messages?", o: ["Appreciate the proposal, explain the distribution constraints, decline exclusivity, and suggest a non-exclusive alternative", "Blame the distributor’s lack of market knowledge and end the relationship", "State the refusal immediately without providing any explanation or reasoning for the decision.", "Hide the refusal in an unclear paragraph and offer no alternative"], a: 0, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "A final-year student is translating the following Nigerian business sentence into formal English: “We don dey review the proposal, and we go back to you next week.” Which translation is most appropriate?", o: ["We are review the proposal, but we had reply you tomorrow.", "We are reviewing the proposal and will respond to you next week.", "We reviewed the proposal and responded to you last week.", "We have review the proposal and would responding next week."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A multimedia researcher is writing the findings section of a report based on questionnaire data from 200 viewers. Which sentence demonstrates appropriate academic and business-report language?", o: ["Interactive documentaries are definitely the future because they are obviously better than all other formats.", "The findings indicate that 62% of respondents preferred interactive documentaries, although the sample was limited to university viewers.", "The questionnaire proves that every audience member will choose interactive documentaries in the same situation, regardless of their background.", "Everyone clearly loves interactive documentaries, so the traditional format is now useless."], a: 1, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "During an appraisal interview, a director asks an editor to describe how she solved a serious post-production deadline problem. Which response structure best demonstrates the STAR technique?", o: ["Situation or task, action taken, and measurable result", "Job title, educational history, and list of personal interests", "Personal opinion, general ability, and desired salary", "Future ambition, hypothetical response, and emotional reaction"], a: 0, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "A film producer must write an email to an international streaming partner requesting permission to postpone delivery of a documentary because post-production quality checks are incomplete. Which sentence best combines professional tone, accurate tense, and a clear action request?", o: ["We are kindly asking to postpone the delivery of the documentary, which is a very necessary and urgent matter for our team to ensure the highest possible quality.", "We are still doing the checks, so you should allow us more time because the film is not ready.", "We are completing the final quality checks and kindly request an extension until 15 November; please confirm whether this revised delivery date is acceptable.", "We have complete the quality checks and request you extending the deadline yesterday."], a: 2, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A final-year multimedia student is translating this formal report sentence into clear Nigerian business English: “The findings suggest that inadequate audience research contributed to the campaign’s limited reach.” Which translation preserves the meaning, register, and grammatical accuracy?", o: ["The findings indicate that the audience research was inadequate, therefore the campaign definitely failed completely.", "The findings are suggesting that audience research was not enough and caused the campaign to reach nobody.", "The findings indicate that insufficient audience research contributed to the campaign’s limited reach.", "The findings suggested audience research contributes to the campaign’s limited reaching."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A Film and Multimedia Studies student is preparing a formal complaint to a streaming platform about delayed payment for licensed content. Which sentence best combines a professional tone, precise vocabulary, and an appropriate call for action?", o: ["We request settlement of the outstanding licence fee by 30 November and would appreciate written confirmation of the payment schedule.", "Your failure to remit the outstanding balance is unacceptable; we demand immediate payment to avoid further escalation of this matter.", "We are writing to complain that you did not pay the money which belongs to us since a long time ago.", "Kindly do the needful concerning the payment issue at your earliest possible convenience."], a: 0, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "A documentary producer is translating the following instruction into formal business English: “Muna check the footage before we send am to the client.” Which version is grammatically and professionally appropriate?", o: ["We should checked the footage before we send them to the client.", "Let us review the footage before sending it to the client.", "We are checking the footages before we sent them to client.", "Let everybody check the footage before we have send it to our clients."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A production company’s report examines whether investing in virtual-reality equipment would improve audience engagement. Which sentence belongs most appropriately in the methodology section?", o: ["The company should purchase the equipment and train two technicians immediately.", "Data were collected through questionnaires administered to 150 visitors at three multimedia exhibitions.", "The investment will substantially transform the company’s future audience experience.", "The findings indicate that most visitors prefer immersive content over conventional documentary formats."], a: 1, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "A multimedia project manager is writing minutes for a meeting about a delayed animation project. Which entry follows the conventions of objective minutes?", o: ["The team engaged in a lengthy and frustrating discussion regarding the delay, but the meeting concluded on a positive note.", "Chinedu unfortunately wasted everyone’s time by giving a very confusing explanation of the delay.", "The manager should have monitored the sound-design unit more carefully from the beginning.", "The team reviewed the revised production schedule and agreed that the sound-design unit would submit its files by 12 December."], a: 3, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "A Nigerian filmmaker is presenting a co-production proposal to a Scandinavian investor whose business culture values precision, evidence, and limited promotional exaggeration. Which opening is most effective?", o: ["Our groundbreaking masterpiece will certainly become the greatest film ever produced in Africa.", "This presentation outlines the project’s audience research, production schedule, budget assumptions, and expected distribution outcomes.", "Let us begin with an extended personal story before explaining the project’s purpose and financial requirements.", "You will be amazed by our incredible idea, even though we will provide the supporting data and evidence later in the presentation."], a: 1, h: "Keep the audience and purpose in view, organize the message clearly, and support key points with relevant evidence." },
  { q: "A multimedia company commissions a report on whether an interactive documentary should be distributed through a subscription platform. The writer has questionnaire data from 240 viewers and interviews with three distributors. Which paragraph best belongs in the report’s introduction?", o: ["This report evaluates the platform’s viability by examining audience interest, distribution costs, and distributor perspectives; data were collected through questionnaires and interviews, although the sample does not represent all potential subscribers.", "The questionnaire responses prove that the proposed documentary will achieve commercial success.", "Given that most viewers expressed a strong preference for subscription platforms, this report suggests that the company should move forward with an immediate investment in the project to capitalize on current market trends and audience demand.", "The platform should be adopted because interactive documentaries are more innovative than conventional films."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A film company is writing a persuasive proposal to obtain funding for a documentary series. Which sentence most effectively applies audience awareness, evidence-based persuasion, and a professional register?", o: ["Investors must provide immediate funding for this series, as a refusal to invest would suggest a lack of commitment to supporting the growth and visibility of talented African filmmakers.", "The series will succeed worldwide, although no audience research, budget, or distribution plan is available.", "Audience research from three regional screenings indicates strong interest in the subject; funding would enable the company to produce and distribute a six-part series to this identified market.", "Everyone will love this exceptional series because it is obviously the most important documentary project ever made."], a: 2, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "A project coordinator is converting an informal production message into a formal email: “We can’t send the final cut today because the editor never finish am. Make una give us more time.” Which version is most appropriate?", o: ["The final cut cannot be delivered today because editing is incomplete. We request an extension until Friday and would appreciate your confirmation.", "The final cut is not send today because the editor has not finish am; kindly do the needful.", "We cannot send the final cut today because the editor did not finish it; please give us more time.", "The editor has not completed the final cut yet, so we would appreciate it if you could grant us an extension to ensure the quality of the final delivery."], a: 0, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "A documentary producer writes to an international distributor after a delivery delay caused by incomplete colour grading. Which sentence best combines accurate tense, formal register, and a tactful request for revised scheduling?", o: ["As colour grading is still in progress, we request an extension until 18 December and would appreciate confirmation of the revised delivery date.", "The colour grading was still progressing, so we are requesting that you had extended the delivery date.", "We request an extension because the editor failed to complete the work, and you must confirm it immediately.", "Since the colour grading process has not yet finished, we kindly request that you grant us additional time for the final delivery of the documentary."], a: 0, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A final-year student is translating this formal report statement into clear, accurate English: “A pesquisa mostrou que os espectadores abandonaram o documentário quando a narração se tornou excessivamente técnica.” Which translation preserves the original meaning and professional register?", o: ["The research showed that the documentary abandoned viewers whenever technical narration had become excessive.", "The research has shown viewers were abandoning the documentary because the narration is too technical.", "The research proves that all viewers rejected the documentary as soon as its narration used technical language.", "The research showed that viewers abandoned the documentary when the narration became excessively technical."], a: 3, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are preparing the executive summary of a report on audience responses to a documentary trailer. The data show that 68% of surveyed viewers found the trailer engaging, but the sample consisted only of university students. Which sentence reports the finding most responsibly?", o: ["The trailer engaged 68% of surveyed viewers, although the university-based sample limits generalisation.", "The trailer will engage 68% of all potential viewers.", "While 68% of students liked the trailer, this specific group does not represent the entire documentary audience.", "The survey proves that the trailer is commercially successful."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are writing minutes after a production meeting in which no agreement was reached about the release date. Which entry is most appropriate?", o: ["The team failed to make a sensible decision about the release date.", "The release date was probably postponed because management seemed uncertain.", "No consensus was reached on the release date; the matter was deferred to the next meeting.", "Disagreements occurred regarding the release date, leading to a heated and unproductive debate."], a: 2, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "You are replying to an international partner who has asked whether your studio can deliver the final subtitles by Friday. The translation is still being checked, but you expect completion by then. Which response is most accurate and tactful?", o: ["We are completing the checks yesterday and can deliver them whenever possible.", "The subtitles are finished, but the final checks may still change the translation.", "We expect to complete the final checks by Friday and will confirm the delivery schedule tomorrow.", "We will definitely deliver the subtitles by Friday, although the review has not begun."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are translating this informal production message into formal English: “If una fit send the revised budget today, we go review am before the meeting.” Which translation is best?", o: ["If you had send the revised budget today, we review it before the meeting.", "When you could send the revised budget today, we would review them before the meeting.", "If you can sent the revised budget today, we will reviewed it before the meeting.", "If you could send the revised budget today, we would review it before the meeting."], a: 3, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are negotiating licensing terms with a distributor who insists on exclusive rights, while your studio needs flexibility to work with other platforms. Which response best applies interest-based, integrative negotiation?", o: ["Reject the demand immediately and insist that your studio’s position is non-negotiable.", "Accept permanent exclusivity to avoid conflict and ensure the relationship remains stable throughout the negotiation process.", "Reveal your minimum acceptable fee before exploring the distributor’s underlying interests.", "Ask what value exclusivity provides and propose limited exclusivity with a defined duration and performance conditions."], a: 3, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "You are preparing a trip report after visiting two potential distribution partners. Your supervisor wants the document to support a decision without reading every detail. Which opening best follows trip-report conventions?", o: ["A personal narrative describing your travel experience and general impressions of the trip", "List of names without dates, locations, outcomes, or follow-up actions", "Complete chronological transcript of every conversation", "Executive summary stating the trip’s purpose, key meetings, major outcomes, and recommendation"], a: 3, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are translating this production update into formal English: “We don finish the rough cut, but we never send am because the client no approve the music.” Which version is most accurate?", o: ["We have completed the rough cut but have not sent it because the client has not approved the music.", "We had completed the rough cut, but we have not send it because the client was not approving the music.", "We have finish the rough cut, but we never sent it because the client has not approve the music.", "We finished the rough cut, but we did not send them because the client did not approve music."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are editing a proposal for an international media investor. Which revision best demonstrates plain, reader-centred Business English?", o: ["The platform will reduce delivery delays by automating subtitle-quality checks.", "The implementation of automated subtitle-quality checks will facilitate the reduction of delivery delays.", "It is important to note that the platform has the capability of possibly reducing delays.", "The platform is a highly innovative solution that will revolutionise delivery processes globally."], a: 0, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "You are writing a negative message to a filmmaker whose grant application cannot be funded this year. The panel valued the project but had limited funds. Which closing best preserves goodwill without making a false promise?", o: ["We regret that your excellent project was unsuccessful because the panel disliked its concept.", "We guarantee funding next year if you submit the same application again.", "We cannot fund the project, and no further correspondence about the decision is necessary.", "We encourage you to apply in the next funding cycle and wish you success with the project."], a: 3, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "You are reviewing a production company’s internal memo before it is sent to staff. The memo says: “Due to the fact that the equipment has not arrived as at today, rehearsals will be postponed until further notice.” Which revision best applies concise, professional Business English?", o: ["Rehearsals will be postponed due to the equipment not arriving as at today.", "Because the equipment has not arrived, rehearsals will be postponed until further notice.", "The equipment has not arrived, therefore rehearsals are postponing until further notice.", "Owing to the fact that the equipment is yet to arrive as at today, rehearsals shall be postponed indefinitely."], a: 1, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "You are translating a Nigerian producer’s instruction into formal English: “Make sure say everybody submits their scripts before the meeting starts.” Which translation is grammatically and professionally appropriate?", o: ["Make sure everybody submit their script before the meeting start.", "Ensure that everyone submits their scripts before the meeting begins.", "Be making sure that everyone submits their scripts before the meeting is starting.", "Ensure everybody has submitted their scripts before the meeting will begin."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are preparing a report for a film festival after interviewing 80 attendees. The data show that most respondents valued the panel discussions, but the sample was collected only from one festival session. Which sentence presents the finding most responsibly?", o: ["Most respondents valued the panel discussions, although the single-session sample limits generalisation.", "The panel discussions were successful because every attendee enjoyed them.", "The interviews prove that all festival audiences prefer panel discussions.", "The findings show that panel discussions should replace all other festival activities."], a: 0, h: "Aim for respectful participation, clarification, objective discussion, and a clearly recorded outcome." },
  { q: "You are writing to a client whose documentary delivery will be delayed because the final sound mix requires correction. Which sentence is grammatically accurate and professionally tactful?", o: ["We will complete the sound mix yesterday and deliver the documentary on Friday.", "We are expecting completing the sound mix by Thursday and request you approving delivery Friday.", "We expect to complete the sound mix by Thursday and request approval for delivery on Friday.", "The sound mix has delayed because the engineers have not corrected it yet."], a: 2, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are translating this informal instruction into formal English: “If the client approve the storyboard, we go start filming next week.” Which version is correct?", o: ["If the client has approve the storyboard, we begin filming next week.", "If the client approves the storyboard, we will begin filming next week.", "If the client approve the storyboard, we would began filming next week.", "If the client approved the storyboard, we will begin filming last week."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are reviewing a proposal that says: “The project will be implemented in a manner that is capable of facilitating the improvement of audience engagement.” Which revision best applies plain English?", o: ["The project shall effectuate audience engagement improvement.", "The project will improve audience engagement.", "The project is capable of possibly facilitating better audience engagement.", "The project will be implemented to facilitate the improvement of engagement."], a: 1, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "You are chairing a production meeting in which two departments disagree about the launch date. Which action best demonstrates effective meeting leadership?", o: ["Interrupt the disagreement and impose your preferred date without discussion.", "Note that one department is being unreasonable and postpone all further discussion until a later date.", "Summarise both positions, identify the decision needed, invite evidence, and record the agreed action.", "Allow the debate to continue without a time limit or decision point."], a: 2, h: "Aim for respectful participation, clarification, objective discussion, and a clearly recorded outcome." },
  { q: "You are editing a funding proposal after discovering that its audience figures came from an unverified social-media post. What is the most ethical revision?", o: ["Retain the figure but describe it as preliminary evidence", "Remove the claim or replace it with a verified source and accurate qualification", "Present the figure without attribution to avoid distracting the reader", "Cite the social-media post as reliable because it supports the proposal"], a: 1, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "You are translating this production update into formal English: “We never receive the footage, so the editor no fit complete the rough cut.” Which version is correct?", o: ["We have not receive the footage, so the editor cannot completing the rough cut.", "We have not received the footage, so the editor cannot complete the rough cut.", "We did not received the footage, so the editor could not completed the rough cut.", "We never received the footages, so the editor is unable completed the rough cut."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are writing a report after surveying viewers about a proposed film festival. The results are mixed, and several respondents skipped questions. Which sentence best demonstrates cautious interpretation?", o: ["The responses prove that viewers strongly support the festival.", "The majority’s opinion represents every potential festival attendee and provides a definitive view of the public.", "The unanswered questions confirm that respondents opposed the festival.", "The responses suggest moderate interest, although missing answers limit the strength of the conclusion."], a: 3, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "You are preparing an email to a distributor after discovering that an attachment contains the wrong budget. Which action best protects clarity and professionalism?", o: ["Forward the original email repeatedly until the correct attachment is noticed", "Send the accurate budget without explanation and leave the earlier figures uncorrected", "Send a brief correction, attach the accurate budget, and identify the superseded file", "Ignore the error because the recipient can compare the figures independently"], a: 2, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "Translate into formal business English: “We don review the proposal, but we never send am because the figures still dey change.”", o: ["We reviewed the proposal, but we never send it because the figures still changed.", "We had reviewed the proposal, but we did not send it because the figures have changed still.", "We have review the proposal, but have not sent them because the figures are still change.", "We have reviewed the proposal, but have not sent it because the figures are still changing."], a: 3, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "Choose the sentence that expresses a report conclusion without introducing unsupported material.", o: ["The survey proves that unclear pricing will reduce every customer’s interest.", "The survey suggests that unclear pricing reduced interest among respondents.", "The survey recommends that the company should redesign its entire pricing system immediately.", "The survey reveals that competitors offered lower prices, although this was not investigated."], a: 1, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A client writes, “Please send the final storyboard when it is ready.” Which reply is clearest and least ambiguous?", o: ["The final storyboard will be sent when it has been made ready.", "We will send the final storyboard by 4:00 p.m. on Friday.", "We are intending to send the final storyboard shortly, subject to readiness.", "We will send the final storyboard as soon as possible at the appropriate time."], a: 1, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "Translate into clear Nigerian business English: “La empresa rechazó la propuesta porque el presupuesto no incluía los costes de distribución.”", o: ["The company rejected the proposal, although the budget included no costs of distributing.", "The company refused the proposal because distribution costs were not including in the budget.", "The company has rejected the proposal because the budget does not included distribution costs.", "The company rejected the proposal because the budget did not include distribution costs."], a: 3, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A report finds that 55% of respondents preferred online screenings, while 45% preferred cinema screenings. Which recommendation is most defensible?", o: ["Replace cinema screenings entirely because online screenings are now universally preferred.", "Conclude that respondents preferred online screenings for every type of film and audience.", "Pilot an online screening programme while retaining selected cinema screenings for comparison.", "Ignore the result because the difference between the groups is not exactly equal."], a: 2, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Translate into formal English: “If una fit approve the revised schedule today, we go inform the crew before close of work.”", o: ["If you could approve the revised schedule today, we inform the crew before work had closed.", "If you can approved the revised schedule today, we will informed the crew before work closes.", "If you could approve the revised schedule today, we would inform the crew before the end of the working day.", "If you approved the revised schedule yesterday, we would have informed the crew before the end of the day."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A report states: “Although 72% of respondents preferred short-form documentaries, the sample consisted of viewers recruited from one university media club.” Which conclusion is most methodologically responsible?", o: ["The sample is too limited to support any conclusion about the surveyed participants.", "Short-form documentaries are preferred by most viewers across every possible audience and distribution context.", "The preference figure is invalid because university students cannot provide useful audience data.", "Short-form documentaries were preferred in this sample, but the finding cannot be generalised confidently to all viewers."], a: 3, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Complete the sentence with the most appropriate form: “By the time the investor arrives, the production team __ the revised budget.”", o: ["would have completed", "has completed", "will have completed", "will complete"], a: 2, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "Translate into clear Spanish: “The distributor requested a revised delivery date because the final subtitles had not been approved.”", o: ["El distribuidor solicitará una fecha revisada porque los subtítulos finales no aprobaron.", "El distribuidor solicitó que la fecha entregara los subtítulos porque no habían revisado.", "El distribuidor solicitó una fecha de entrega revisada porque los subtítulos finales no habían sido aprobados.", "El distribuidor había aprobado los subtítulos finales porque solicitó una fecha de entrega revisada."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A producer wants to reject a funder’s proposed contract clause requiring permanent exclusive rights. Which sentence best protects the relationship while clearly stating the studio’s interest?", o: ["We reject the clause because permanent exclusivity is unacceptable and will not be discussed further.", "We appreciate the offer and accept the clause, provided that the contract remains subject to later renegotiation.", "We appreciate the offer; however, we can consider exclusivity only for a defined period with performance conditions.", "We are unable to accept the clause at present, although permanent exclusivity may be acceptable under unspecified future circumstances."], a: 2, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "Translate into formal English: “We no fit release the trailer until the legal team don approve the music rights.”", o: ["We could not release the trailer until the legal team approve the music rights.", "We cannot release the trailer until the legal team approves the music rights.", "We cannot released the trailer until the legal team has approve the music rights.", "We cannot release the trailer unless the legal team approved the music rights yesterday."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A report finds that viewers enjoyed a documentary’s subject but abandoned it when the narration became too technical. Which recommendation best follows from the evidence?", o: ["Conclude that viewers generally dislike educational documentaries.", "Replace the documentary’s subject with a more entertaining topic.", "Simplify the narration while preserving the subject’s substantive content.", "Add more technical terminology to attract specialist viewers."], a: 2, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Choose the sentence that uses the present perfect correctly to describe a completed production task with present relevance.", o: ["The editor has been uploaded the final cut, so the client can review it now.", "The editor has upload the final cut, so the client can review it now.", "The editor uploaded the final cut yesterday, so the client has reviewed it now.", "The editor has uploaded the final cut, so the client can review it now."], a: 3, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "Translate into clear Spanish: “The production team postponed the shoot because heavy rain damaged the location.”", o: ["El equipo de producción fue pospuesto porque la lluvia intensa estaba dañando el rodaje.", "El equipo de producción ha pospuesto el rodaje porque la locación dañará la lluvia intensa.", "El equipo de producción pospondrá la lluvia porque el rodaje dañó la locación.", "El equipo de producción pospuso el rodaje porque la lluvia intensa dañó la locación."], a: 3, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A producer receives two proposals: one promises a larger audience but provides no evidence; the other presents modest projections supported by verified data. Which decision best reflects responsible business communication?", o: ["Select the modest proposal automatically because conservative estimates are always accurate.", "Prefer the evidence-based proposal and request further data before committing.", "Treat both projections as equally reliable because all proposals are interpretive.", "Prefer the larger projection because ambition is more persuasive than evidence."], a: 1, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "Translate into formal English: “We go send the revised proposal once the legal team don approve am.”", o: ["We would send the revised proposal once the legal team approved it yesterday.", "We will sent the revised proposal once the legal team has approve it.", "We will send the revised proposal once the legal team has approved it.", "We send the revised proposal once the legal team approve it."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A report finds that poor internet access reduced participation in an online film screening. Which recommendation follows most logically from the finding?", o: ["Replace the film with a shorter production.", "Provide downloadable content and a low-bandwidth viewing option.", "Increase the technical vocabulary in the promotional material.", "Conclude that audiences dislike online film screenings."], a: 1, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Choose the sentence with the most appropriate business collocation.", o: ["The committee arrived to a decision on the distribution strategy.", "The committee reached a decision on the distribution strategy.", "The committee made a discussion on the distribution strategy.", "The committee did a decision on the distribution strategy."], a: 1, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "Translate into clear Spanish: “The producer asked whether the revised budget included post-production costs.”", o: ["El productor preguntó si los costes de posproducción revisaron el presupuesto.", "El productor preguntó que el presupuesto revisado incluyó los costes de posproducción.", "El productor pidió cuándo el presupuesto revisado incluía los costes de posproducción.", "El productor preguntó si el presupuesto revisado incluía los costes de posproducción."], a: 3, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A client says, “Your report is difficult to follow because the findings and recommendations are mixed together.” Which revision best solves the problem?", o: ["Separate evidence-based findings from numbered, action-oriented recommendations.", "Combine the findings and recommendations into one longer paragraph.", "Present recommendations first and support them with unrelated new evidence.", "Remove the findings and retain only the recommendations."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A Nigerian documentary studio is preparing a formal report on audience retention during a mobile-streaming pilot. The questionnaire shows that 64% of respondents abandoned videos when subtitles loaded slowly, while interviews indicate that some viewers also found the subtitle wording too technical. Which paragraph best integrates the evidence without overstating the findings?", o: ["The results show that viewers dislike subtitles and that subtitles should be removed from future productions.", "The findings suggest that slow subtitle loading was associated with audience abandonment, while interview responses indicate that technical wording may also have reduced comprehension; because the sample was limited to the pilot audience, the results should not be generalised to all mobile viewers.", "The data proves that slow subtitle loading was the sole cause of audience abandonment across the entire mobile-streaming market; therefore, the studio must immediately overhaul its technical infrastructure to ensure that all future video content is delivered with instantaneous subtitle synchronization.", "The interviews invalidate the questionnaire because qualitative evidence cannot support a report’s findings."], a: 1, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Translate the following formal Spanish sentence into accurate professional English: “Aunque la campaña aumentó el alcance del documental, no produjo un incremento significativo de las suscripciones.”", o: ["Although the documentary increased the campaign, it did not subscribe to a significant audience or reach its goals.", "Although the campaign increased the documentary’s reach, it did not produce a significant increase in subscriptions.", "Although the campaign increased the documentary’s subscriptions, it did not produce significant reach.", "The campaign has increased the reach, therefore subscriptions were significantly produced."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A production manager is writing an email to an international partner. The partner has not approved the revised shooting schedule, and filming cannot begin without that approval. Which sentence uses the conditional structure, tense, and register most accurately?", o: ["If you will approve the revised schedule by Friday, we began filming on Monday.", "If you approved the revised schedule by Friday, we will have begin filming on Monday.", "If you approve the revised schedule by Friday, we will begin filming on Monday.", "If you approve the revised schedule by Friday, we would began filming on Monday."], a: 2, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A film company has received a complaint that a promotional trailer misrepresented the documentary’s subject. The company agrees that the wording was unclear but has not yet established whether viewers suffered financial loss. Which response best demonstrates a tactful negative-message strategy?", o: ["Apologize for the financial loss immediately, even though the company has not yet confirmed that any such loss actually occurred.", "Acknowledge the concern, clarify the wording, explain the corrective action, and avoid claiming facts that have not been established.", "Deny all responsibility immediately and state that viewers should have interpreted the trailer more carefully.", "Ignore the complaint until the legal investigation is complete and provide no interim clarification."], a: 1, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "A final-year multimedia student is translating a report recommendation into formal English: “La empresa debería ofrecer una versión de baja resolución para que los espectadores con conexiones lentas puedan ver el documental.” Which translation is most accurate?", o: ["The company should offer a low-resolution version so viewers with slow connections could have watched the documentary.", "The company should provided a low-resolution version for viewers which their connections are slowly.", "The company would provide a low-resolution version because slow connections have watched the documentary.", "The company should provide a low-resolution version so that viewers with slow connections can watch the documentary."], a: 3, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A Nigerian documentary studio surveyed 180 mobile viewers about a proposed low-bandwidth streaming service and then interviewed eight participants to explain the questionnaire results. In the report, which methodology statement most accurately identifies the design, scope, and limitation of the study?", o: ["The study proves that all mobile viewers prefer low-bandwidth streaming because 180 participants were surveyed.", "The study used interviews only, so the numerical questionnaire results should be excluded from the report.", "The methodology belongs in the recommendations section because the study focuses on proposing a future streaming strategy rather than analyzing current data.", "The study combined a questionnaire with follow-up interviews; it examined viewer preferences during the pilot, but its non-random sample limits generalisation."], a: 3, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "A final-year student is translating this report sentence into formal English: “Aunque los espectadores valoraron la calidad visual, muchos abandonaron el documental porque la narración era demasiado técnica.” Which translation is most accurate?", o: ["Although viewers have appreciated the visual quality, many abandon the documentary because the narration is too technical.", "Although the documentary appreciated viewers’ visual quality, many narrations abandoned it because the subject was technical.", "Although viewers appreciated the visual quality, many abandoned the documentary because the narration was too technical.", "Viewers valued visual quality, although the documentary was abandoned because technical narrations had been many."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A production company is writing a report after discovering that a promotional campaign generated high online engagement but few completed streams. Which sentence correctly uses contrast and avoids confusing a finding with a recommendation?", o: ["The campaign generated substantial online engagement; therefore, the company should immediately increase its advertising budget to capitalize on this momentum.", "Although the campaign generated substantial online engagement, the low completion rate suggests that further research into audience retention is needed.", "Because online engagement was high, the campaign successfully retained viewers throughout the documentary.", "The low completion rate proves that the promotional campaign failed completely."], a: 1, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "During a negotiation, an international distributor offers a large advance in exchange for permanent exclusive rights to a documentary. The studio needs immediate funding but wants to preserve future distribution flexibility. Which response best applies BATNA analysis, interest-based negotiation, and precise business English?", o: ["We value the proposed advance; could we explore time-limited exclusivity while we assess alternative financing and distribution options?", "We will decide after revealing our minimum acceptable terms and cancelling discussions with other potential partners.", "We accept permanent exclusivity because the advance is more important than future distribution.", "We reject the advance because permanent exclusivity is an unacceptable term that fails to protect our long-term distribution interests."], a: 0, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "A student is editing an executive summary of a feasibility report on an immersive documentary installation. The evidence indicates strong audience interest, high equipment costs, and uncertain long-term revenue. Which summary best preserves balance, relevance, and decision-making value?", o: ["The installation shows strong audience potential, but its viability depends on controlling equipment costs and testing revenue through a limited pilot.", "The installation should be rejected because the uncertain revenue streams and high equipment costs make the entire immersive documentary project impractical to pursue.", "The installation will achieve long-term profitability once launched, although no financial evidence supports that prediction.", "The installation is commercially viable because audience interest always outweighs high production and equipment costs."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A Nigerian documentary studio is preparing a feasibility report on an augmented-reality exhibition for international investors. Pilot data show strong visitor interest, but the sample came from one university festival; equipment costs remain uncertain, and no long-term revenue data exist. Which executive-summary statement is most defensible?", o: ["The exhibition appears promising, but a limited pilot and uncertain costs require a controlled trial before full investment.", "The exhibition will achieve international success once the equipment is purchased.", "The exhibition is commercially viable because strong visitor interest guarantees future revenue.", "The project should be rejected because university festival data is insufficient to inform professional business decisions."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Translate into formal English: “Aunque la plataforma aumentó la visibilidad del documental, no consiguió convertir ese interés en suscripciones pagadas.”", o: ["Although visibility was increasing, the documentary had not managed to convert that interest into any paid subscriptions.", "Although the platform increased the documentary’s visibility, it did not convert that interest into paid subscriptions.", "The platform has converted paid subscriptions because the documentary increased its visibility.", "Although the documentary increased the platform’s subscriptions, it did not achieve visible interest."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "Complete the production report sentence with the most appropriate tense and modal structure: “By the time the distributor reviews the revised cut, the legal team __ the music-rights documentation, provided that the composer __ the licence form today.”", o: ["would verify; signed", "has verified; will sign", "will verify; has signed", "will have verified; signs"], a: 3, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A post-production supervisor wants to express disagreement during a multinational meeting without threatening face or closing discussion. Which utterance is most appropriate?", o: ["I understand the concern; however, could we examine whether the proposed deadline is realistic given the remaining sound work?", "The deadline is impossible because management has failed to understand the production process.", "You are wrong about the deadline, and the sound team will not accept your decision.", "I disagree completely with that timeline, so there is no reason to consider the proposed schedule any further at this stage."], a: 0, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "Translate into clear Spanish: “The report recommends simplifying the narration while retaining the documentary’s substantive content.”", o: ["El informe recomienda que la narración simplifique el documental y elimine su contenido principal.", "El informe recomienda simplificar la narración sin eliminar el contenido sustantivo del documental.", "El informe recomendó que el documental conservara una narración técnicamente más compleja.", "El informe recomienda simplificar el contenido y conservar únicamente la narración del documental."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A final-year Film and Multimedia Studies student is translating this Spanish sentence for a formal feasibility report: “Aunque el proyecto recibió una respuesta favorable durante la prueba piloto, los costes de mantenimiento podrían limitar su viabilidad a largo plazo.” Which translation preserves the contrast, register, and cautious meaning?", o: ["Although the pilot limited the project, its favourable maintenance costs could receive a long-term response.", "Although the project has received favour during the pilot, maintenance costs will limit its viability in the long term.", "Although the project received a favourable response during the pilot, maintenance costs could limit its long-term viability.", "The project received a favourable response, so its maintenance costs guarantee long-term viability."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A production report states: “If the distributor had approved the revised delivery schedule, the studio would have avoided the additional storage costs.” What does this conditional sentence communicate?", o: ["The approval is still expected, so the costs will be avoided.", "The studio avoided the costs because approval was received.", "The distributor regularly approves schedules before storage begins.", "The approval did not occur, and the additional costs were incurred."], a: 3, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "A report on a documentary’s online performance states: “Engagement increased substantially after the trailer was shortened; however, the available data do not establish that duration alone caused the increase.” Which interpretation demonstrates appropriate critical reading?", o: ["The shorter trailer coincided with higher engagement, but causation remains uncertain.", "The shorter trailer definitively caused the entire increase in engagement.", "Increased engagement proves that longer trailers are ineffective in every market.", "The data are unusable because no causal conclusion can be made."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Translate into formal English: “La productora habría aceptado la propuesta si el distribuidor hubiera ofrecido condiciones más flexibles.”", o: ["The production company would have accepted the proposal if the distributor had offered more flexible terms.", "The production company will accept the proposal if the distributor offers flexible terms.", "The distributor would have accepted the company’s proposal if production had become more flexible.", "The production company accepted the proposal because the distributor offered flexible terms."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A multimedia company is revising an executive summary after finding that its original market projection relied on an outdated industry report. Which revision best demonstrates research ethics, source integration, and professional caution?", o: ["Replace the outdated projection with a current, verifiable source and explain any remaining limitations.", "Retain the projection but omit the publication date to avoid weakening the argument.", "Reframe the projection as an internal estimate while omitting the original source to maintain authority.", "Cite the outdated report as current because its prediction supports the business proposal."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are editing a funding proposal after discovering that its audience-growth forecast combines figures from three different years without identifying the dates. What is the most ethical revision?", o: ["Keep the largest figure because it gives investors the clearest growth picture.", "Average the figures and present one projection without discussing the dates.", "Remove the source details because they distract from the proposal’s main argument.", "Separate the figures by year, cite each source, and explain the basis of the forecast."], a: 3, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "You are translating this production update into formal English: “We had already finish the rough cut before the client ask for major changes.” Which version is grammatically correct?", o: ["We had already finished the rough cut before the client requested major changes.", "We already finished the rough cut before the client had request major changes.", "We had already finishing the rough cut before the client was requesting major changes.", "We have already finish the rough cut before the client has requested major changes."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are chairing a meeting in which the marketing team claims that high social-media impressions prove a trailer was successful, while the analytics team reports a low completion rate. What should you do first?", o: ["Accept the marketing team’s conclusion because impressions are the most visible metric.", "Combine all metrics into one figure before examining what each metric measures.", "Reject the campaign immediately because a low completion rate proves the entire marketing effort was a failure.", "Distinguish awareness from retention and ask both teams to support their claims with relevant evidence."], a: 3, h: "Aim for respectful participation, clarification, objective discussion, and a clearly recorded outcome." },
  { q: "Translate into clear Spanish: “The studio postponed the release because the distributor had not confirmed the revised schedule.”", o: ["El estudio pospondrá el calendario porque el distribuidor no confirma el estreno.", "El estudio ha confirmado el estreno porque el distribuidor pospuso el calendario revisado.", "El estudio pospuso el estreno porque el distribuidor no había confirmado el calendario revisado.", "El distribuidor pospuso el estreno porque el estudio no había confirmado la versión revisada."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are preparing a recommendation after a pilot screening reveals strong audience interest but serious accessibility problems for viewers with hearing impairments. Which recommendation is most directly supported by the evidence?", o: ["Expand the programme immediately because audience interest outweighs accessibility concerns.", "Add accurate captions and audio-description options before expanding the screening programme.", "Replace the documentary’s subject because accessibility problems indicate weak content.", "Conclude that viewers with disabilities are not part of the project’s intended audience."], a: 1, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are preparing a bilingual production agreement. Translate this clause into accurate formal English: “La distribuidora podrá ampliar el plazo si la productora demuestra que el retraso se debió a circunstancias ajenas a su control.”", o: ["The distributor could have extended the deadline because the production company demonstrated an uncontrollable delay.", "The distributor must extend the deadline whenever the production company says the delay was outside control.", "The distributor may extend the deadline if the production company demonstrates that the delay was due to circumstances beyond its control.", "The production company may extend the deadline if the distributor proves that the delay was caused by circumstances that were outside of its control."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are reviewing a report on a virtual-reality exhibition. Attendance was high, but the questionnaire had a 38% response rate and collected no data on repeat visits. Which conclusion is most defensible?", o: ["The lack of repeat-visit data confirms that the exhibition failed to create any lasting impact on the audience.", "The response rate shows that most non-respondents were dissatisfied with the exhibition.", "High attendance proves that visitors found the exhibition valuable and would return.", "High attendance indicates initial interest, but the evidence is insufficient to establish sustained engagement."], a: 3, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are writing to a client after discovering that a delivery date in the contract is impossible because a required permit is delayed. Which sentence is clearest and most professionally responsible?", o: ["The delivery date has been revised, although the client’s approval is still required.", "We cannot deliver on time because the authorities have caused this problem.", "Due to the fact that the permit is not yet ready, delivery may perhaps be postponed at some point.", "Because the permit remains pending, we request approval to revise the delivery date to 20 January."], a: 3, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "You are translating this formal English sentence into Spanish for a festival report: “The findings do not demonstrate that the promotional campaign caused the increase in attendance.”", o: ["La campaña promocional no demuestra que los resultados hayan causado un aumento de asistencia.", "Los resultados no demuestran que la campaña promocional haya causado el aumento de la asistencia.", "Los resultados no demuestran que la campaña haya aumentado la asistencia.", "Los resultados no demuestran que la campaña promocional fuera la causa del incremento en la asistencia."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are negotiating with a streaming platform that offers a larger marketing budget but demands approval rights over all editorial decisions. Your studio wants promotion without losing creative control. What is the strongest response?", o: ["Request the platform's final position before detailing your studio's specific creative priorities and requirements.", "Accept all approval rights because the larger budget guarantees creative success.", "Separate the interests: propose marketing support with approval limited to brand, legal, and technical matters.", "Reject the offer entirely because any platform involvement compromises independence."], a: 2, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "You are editing a bilingual distribution contract. Translate into accurate formal English: “La plataforma podrá retirar el contenido si el productor no corrige las deficiencias técnicas dentro del plazo acordado.”", o: ["The producer may remove the platform if the technical content does not agree within the period.", "The platform will remove the content because the producer corrected the technical deficiencies after the agreed period.", "The platform could have removed the content if the producer had corrected the deficiencies within the agreed period.", "The platform may remove the content if the producer does not correct the technical deficiencies within the agreed period."], a: 3, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are reviewing a report whose survey found that viewers preferred shorter episodes, but interviews revealed that some viewers valued longer episodes when the subject was complex. Which conclusion best represents both forms of evidence?", o: ["Interview responses should replace the survey because qualitative evidence is more reliable.", "The conflicting results make it impossible to draw any useful conclusion.", "Episode length should reflect subject complexity, since audience preferences vary by content.", "Viewers generally prefer short episodes, so all future episodes should be shortened."], a: 2, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are writing to a partner who missed a contractual approval deadline, delaying production. Which sentence is firm but professional and uses the correct conditional structure?", o: ["If approval is not received by Friday, we will revise the production schedule.", "If approval had not received by Friday, we will have revised the production schedule.", "If approval was not received by Friday, we revised the production schedule.", "If approval will not be received by Friday, we would revise the production schedule."], a: 0, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "You are translating this formal English sentence into Spanish for an international co-production report: “The parties agreed to review the revenue-sharing formula after the pilot phase.”", o: ["Las partes acordarán que la fórmula revisó los ingresos durante la fase piloto.", "Las partes acordaron revisar la fórmula de reparto de ingresos después de la fase piloto.", "Las partes revisaron la fase piloto antes de acordar compartir la fórmula de ingresos.", "Las partes acordaron que los ingresos compartirían la revisión de la fase piloto."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are deciding whether to include a striking industry statistic in a funding proposal. The statistic comes from an unattributed social-media post and cannot be verified. What should you do?", o: ["Include it but describe it as an established industry fact.", "Include it without attribution because it strengthens the proposal.", "Exclude it or replace it with a verifiable, properly cited source.", "Present it as an estimate and omit the uncertainty."], a: 2, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "You are translating a production update into formal English: “We don complete the subtitles, but the client never approve the final version.” Which sentence is correct?", o: ["We had completed the subtitles, but the client never approves the final version.", "We have completed the subtitles, but the client has not approved the final version.", "We completed the subtitles, but the client has not approve the final version.", "We have complete the subtitles, but the client did not approved the final version."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are writing a report after a pilot screening. Attendance was high, but only 30% of attendees completed the feedback form. Which conclusion is most responsible?", o: ["The high attendance indicates interest, but the incomplete feedback limits conclusions about audience satisfaction.", "The low completion rate of the feedback forms proves that the remaining attendees disliked the screening.", "High attendance proves that most attendees were satisfied with the screening.", "The pilot was unsuccessful because fewer than half of attendees completed the form."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are negotiating with a distributor that wants permanent exclusive rights, while your studio needs future flexibility. Which proposal best reflects integrative negotiation?", o: ["Reject exclusivity immediately and end the negotiation.", "Offer limited exclusivity for a defined period in exchange for a stronger advance and performance targets.", "Disclose the studio’s minimum acceptable terms before exploring the distributor’s specific interests.", "Accept permanent exclusivity because the advance is financially attractive."], a: 1, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "You are translating this formal report sentence into Spanish: “The findings suggest that unclear pricing reduced interest among potential subscribers.”", o: ["Los hallazgos sugieren que el interés de los suscriptores potenciales redujo la claridad de los precios actuales.", "Los resultados demuestran que los suscriptores redujeron los precios poco claros.", "Los resultados sugieren que los precios poco claros redujeron el interés de los posibles suscriptores.", "Los resultados sugirieron que los precios claros aumentaron el interés de todos los suscriptores."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A film-production company is preparing a feasibility report on establishing a multimedia studio. Which combination best reflects the report’s purpose and structure?", o: ["Evaluating employees’ punctuality, appearance, and promotion prospects", "Assessing physical and economic viability, presenting evidence, concluding objectively, and making conclusion-based recommendations", "Recording only the team’s travel activities and informal impressions", "Using emotional appeals, testimonials, and persuasive marketing tactics to promote the studio to potential investors and stakeholders"], a: 1, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A director must reject a client’s request to use copyrighted footage in a documentary while preserving the relationship. Which communication strategy is most appropriate?", o: ["Avoid explaining the decision and imply that the client is personally responsible for the refusal to shift the blame away from the director.", "Begin with an accusation, disclose confidential legal details, and end without an alternative", "Use an informal message containing jokes, abbreviations, and an immediate demand for payment", "Use an indirect approach: acknowledge the request, explain the rights limitation, state the refusal clearly, and offer a lawful alternative"], a: 3, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "A final-year multimedia student is presenting research on audience responses to virtual reality films. Which presentation plan best demonstrates effective business communication principles?", o: ["Rely on spontaneous speech, use unexplained statistics, and discourage audience interaction to maintain a sense of mystery and authority.", "Display dense paragraphs on every slide, read them verbatim, and omit the conclusion to maximize content", "Define the audience and purpose, organize the talk logically, use concise visuals, rehearse delivery, and reserve time for questions", "Begin with technical details, avoid audience analysis, and use decorative visuals unrelated to the findings"], a: 2, h: "Keep the audience and purpose in view, organize the message clearly, and support key points with relevant evidence." },
  { q: "During a production meeting, the chair must convert a heated discussion about a delayed film project into accurate minutes. Which approach is correct?", o: ["Replace disagreements with a unanimous decision to make the organisation appear efficient", "Transcribe every utterance, including jokes, interruptions, and personal opinions, to ensure a complete record of the meeting", "Identify the most persuasive speaker as responsible for all actions discussed", "Record the issue, key decisions, assigned responsibilities, deadlines, and unresolved matters in neutral third-person language"], a: 3, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "A multimedia company is negotiating distribution rights with an international streaming platform. Which strategy best reflects integrative negotiation and intercultural competence?", o: ["Prioritize personal rapport, employ aggressive interruptions, and treat the negotiation as a fixed win–lose contest to ensure the company secures the maximum possible gain.", "Reveal the company’s minimum acceptable terms immediately and reject all proposals that do not meet them", "Investigate both parties’ interests, develop mutually beneficial options, use objective criteria, protect the BATNA, and adapt to cultural communication norms", "Avoid discussing cultural expectations because business English eliminates all intercultural misunderstandings"], a: 2, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "A final-year film student is writing an external complaint letter to a distributor about damaged exhibition equipment. Which revision best applies business-letter conventions, positive professional tone, and a clear call to action?", o: ["State the purchase details, describe the damage objectively, request a specific remedy, identify the enclosure, and close with a response deadline", "Begin with an angry accusation, omit the receipt, and demand immediate compensation without explaining the desired remedy", "Describe the company’s reputation at length, conceal the defect until the final sentence, and use “To Whom It May Concern” despite knowing the recipient’s name", "Use slang and informal abbreviations, place several unrelated complaints in one paragraph, and end without requesting action"], a: 0, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "A multimedia researcher is preparing the introduction to a report on students’ use of streaming platforms. Which version best satisfies the required report-writing elements?", o: ["It presents recommendations first, introduces new evidence in the conclusion, and omits the participants because the topic is generally understood", "It summarizes unrelated literature, uses emotional language, and replaces research questions with broad promotional claims", "It establishes context, defines the problem, states the research questions, explains the questionnaire method and sample, identifies limitations, and previews the findings", "It lists personal opinions about streaming, describes the questionnaire in the appendix only, and treats assumptions as established findings"], a: 2, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "A film company wants to send a tactful reminder to a cinematographer who has not submitted footage. Which email best demonstrates reader-centred, concise, and professional communication?", o: ["“Hi, Please kindly send the things in details whenever possible. It is open for submission every day.”", "“URGENT!!! Where is the footage??? Kindly revert back ASAP for our perusal!!!”", "“Subject: Footage submission—revised deadline. Dear Ada, I’m following up on the footage requested on 3 May. Please send the files by 10 May, or let me know today if you need an extension. Kind regards, Tunde.”", "“Dear Ada, I am writing to express my disappointment regarding the missing footage. This delay is unacceptable. Please submit all files immediately and copy the entire production team on your response.”"], a: 2, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "During an appraisal interview, a production supervisor asks a sound editor to explain how she solved a serious recording problem on location. Which response best applies the STAR technique?", o: ["“During the night shoot, background noise affected the dialogue; I isolated the problem, repositioned the microphones, and used a backup recorder, resulting in clean usable tracks.”", "“I am hardworking, creative, and good with sound, so I usually solve difficult production problems.”", "“If a similar problem occurs in the future, I would likely consult with the lead engineer or the production manager to ensure that we have a more robust contingency plan in place for us.”", "“The location was difficult, the director was impatient, and the equipment was old, so the problem was unavoidable.”"], a: 0, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "A Nigerian documentary producer is negotiating with a Scandinavian broadcaster whose representatives prefer precise data, limited small talk, and time for questions. Which communication plan best demonstrates intercultural competence and effective negotiation?", o: ["Avoid an agenda, reveal the producer’s minimum price immediately, and interrupt frequently to demonstrate confidence", "Begin with extended personal stories, use exaggerated promotional claims, and treat requests for evidence as signs of distrust", "Send a structured agenda, present verifiable audience and budget data, distinguish positions from interests, invite clarification, and reserve time for questions", "Rely on silence and indirect hints alone, assuming both parties interpret pauses and disagreement identically"], a: 2, h: "Look beyond stated positions to the interests involved, clarify the terms, and seek options that protect both sides’ priorities." },
  { q: "A film-production company wants to announce that a scheduled shoot has been cancelled because a key location is unavailable. Which sentence uses the most appropriate formal, concise, and positive business English?", o: ["The location is opened, but the shoot is cancelled anyhow.", "We cannot shoot there now, so everything has become impossible.", "The shoot has been rescheduled because the location is unavailable.", "The shoot was cancelled due to some issues and things."], a: 2, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "Translate the following sentence into the most accurate formal English: “Пожалуйста, подтвердите получение сценария и сообщите, когда вы представите свои замечания.”", o: ["Confirm the script has been received and say the time you bring your remarks.", "Kindly confirm that you received the script and inform when you will present your criticisms.", "Please confirm the receiving of the script and tell when you will give your observations.", "Please confirm receipt of the script and indicate when you will submit your comments."], a: 3, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A multimedia researcher is revising this sentence for a report: “The questionnaire was distributed to 120 final-year students, and the responses were analysed.” Which revision best preserves an objective academic style while improving clarity?", o: ["The researcher has distribute the questionnaire to 120 final-year students and analyse their responses.", "We distributed the questionnaire to 120 final-year students, and the responses analysed us.", "The questionnaire distributed 120 final-year students, and it analysed the responses.", "The researcher distributed the questionnaire to 120 final-year students and analysed their responses."], a: 3, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "A film editor is writing an email to a client whose requested changes cannot be completed by the original deadline. Which completion best uses a tactful negative-message structure?", o: ["Because the additional edits require further colour correction, we can deliver the revised cut on Friday instead.", "We cannot meet the deadline because your recent requests require more time for the necessary technical adjustments.", "Unfortunately, the deadline is impossible, so there is nothing more to discuss.", "Your changes are too many; perhaps you should find another editor."], a: 0, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "A final-year student is translating this business instruction into formal English: “До начала презентации проверьте проектор, раздайте участникам повестку и оставьте время для вопросов.” Which translation is most accurate?", o: ["Before the presentation starts, inspect the projector, give out the discussion, and reserve questions.", "Before presentation, control the projector, share the topics, and leave questions.", "Before the presentation, check the projector, distribute the agenda, and allow time for questions.", "Before presenting, check on the projector, circulate the meeting, and permit questioning time."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A film studio’s post-production department has repeatedly missed delivery dates because editors receive contradictory instructions from different producers. Rewrite the following sentence in clear, professional English using the present perfect and an appropriate business collocation: “The editors missed deadlines many times because the producers gave different instructions.”", o: ["The editors have missed deadlines repeatedly because the producers are issued contradictory instructions.", "The editors repeatedly miss deadlines because the producers have been conflicting instructions.", "The editors have repeatedly missed deadlines because the producers have issued conflicting instructions.", "The editors had repeatedly missed deadlines because the producers issue different instructions."], a: 2, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "Translate this formal production email into the most accurate English: “Просим вас подтвердить, что окончательная версия фильма будет доставлена до пятницы.”", o: ["Please confirm us that the definitive movie will deliver on Friday.", "Kindly confirm that the final version of the film will be delivered before Friday.", "We kindly ask you to confirm that the final version of the film will be delivered by Friday.", "We request you confirming the final film version is delivered until Friday."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A documentary producer is writing the findings section of a report based on questionnaire data. Which sentence uses the most appropriate cautious academic language?", o: ["The findings prove that limited internet access always reduces students’ participation in online film courses.", "The findings are suggesting that limited internet access definitely reduced every student’s participation.", "The findings suggested that limited internet access must reduce students’ participation in online film courses.", "The findings suggest that limited internet access may reduce students’ participation in online film courses."], a: 3, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "Complete the sentence with the correct business-English collocation and preposition: “The production manager is responsible  obtaining location permits and accountable  the executive producer.”", o: ["with; by", "of; for", "to; of", "for; to"], a: 3, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A multimedia company is responding to a client who has requested an unrealistic number of revisions. Select the most tactful sentence using an appropriate alternative and a future-oriented closing.", o: ["Perhaps we could attempt a few more revisions if the editor happens to find some extra time in their current schedule.", "Your request is unreasonable, and we will not consider any further changes.", "We cannot do all these revisions, so you must reduce your demands immediately.", "We can complete two further revision rounds by Monday and discuss additional changes after reviewing the revised cut."], a: 3, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "You are preparing the executive summary of a report on declining cinema attendance. Your questionnaire shows that ticket prices, rather than film quality, were the most frequently reported concern. Which sentence presents this finding accurately and cautiously?", o: ["The questionnaire indicates that ticket prices were the most frequently reported concern.", "Ticket prices were reported as the only reason for the decline.", "The questionnaire is indicating ticket prices have definitely caused declining attendance.", "The questionnaire proves that ticket prices caused the decline for every respondent."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are translating a production memo into formal English: “До утверждения бюджета продюсер должен представить два альтернативных плана.” Which translation is most accurate?", o: ["Before the budget is approved, the producer must present two alternative plans.", "Before approving the budget, two alternative plans must present the producer.", "Until the budget approves, the producer should presenting two alternate planning.", "Before the approved budget, the producer must present two alternatives plans."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are writing the conclusion of a report after finding that 68% of surveyed students prefer online tutorials, while the sample included only 50 students from one department. Which conclusion is most responsible?", o: ["Most students prefer online tutorials, and these results can be applied to the entire university population without further study.", "Online tutorials should replace classroom teaching immediately.", "The findings suggest strong interest in online tutorials among the surveyed students, although wider research is needed.", "The survey proves that online tutorials are the best teaching method for all students."], a: 2, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are replying to a client who has not supplied the release forms needed for a documentary. Choose the sentence with correct tense, preposition, and professional tone.", o: ["We have not received the release forms required for the documentary.", "We did not yet receive the release forms necessary on the documentary.", "We are not receiving the release forms required for documentary.", "We have not received yet the release forms required to the documentary."], a: 0, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are chairing a tense production meeting. One member proposes postponing the launch, while another objects. Which intervention best demonstrates polite disagreement and moves the discussion toward a decision?", o: ["We must adhere to the original plan because the deadline is fixed and cannot be changed at this stage.", "You are wrong, and postponing the launch would be a poor decision.", "I understand that concern; however, could we compare the risks of postponing with those of proceeding?", "I disagree completely, so let us move to the next agenda item."], a: 2, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are preparing a trip report after visiting two potential research partners for a documentary project. Your notes include dates, locations, people met, major findings, and a proposed follow-up. Which opening best follows the required trip-report style?", o: ["Personal diary describing every conversation in chronological detail", "A promotional introduction highlighting the company’s reputation and prestige", "Executive summary stating the trip’s purpose, main accomplishments, and recommendation", "Unstructured list of impressions without dates or outcomes"], a: 2, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are writing minutes for a production meeting in which no agreement was reached about the release date. Which sentence records the outcome objectively and correctly?", o: ["Everyone agreed that the release date was probably unsuitable.", "The production team failed to make the correct decision.", "No consensus was reached; the matter was deferred to the next meeting.", "The chair rejected the proposed date following a lengthy argument."], a: 2, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "You are translating a client’s message into formal English: “Мы будем признательны, если вы отправите исправленный бюджет до конца дня.”", o: ["We are appreciating that you can send the budget correction at the end day.", "We appreciate you will send the corrected budget until the day ends.", "We would appreciate it if you could send the revised budget by the end of the day.", "We will be grateful if you could send the corrected budget before the end of the day."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are editing a film-company policy sentence to remove nominalisation and improve clarity: “The implementation of a review of the safety procedures will be undertaken by the production manager.”", o: ["The production manager will undertake the implementation of a review on safety procedures.", "The production manager will review the safety procedures.", "A review of the safety procedures will be implemented by the production manager.", "The safety procedures’ review implementation will be done by production management."], a: 1, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "You are evaluating a proposal for a new campus cinema. The report shows strong student demand, but it also identifies uncertain funding and no evidence about long-term operating costs. What is the most defensible recommendation?", o: ["Approve permanent construction since high student demand guarantees the project's long-term success.", "Recommend immediate expansion while leaving operating costs for later review.", "Reject the project because any financial uncertainty makes it unviable.", "Approve a pilot project subject to a detailed financial assessment and confirmed funding."], a: 3, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are revising a report after discovering that your questionnaire reached only 18 respondents, all from one production unit. Which sentence most responsibly presents the limitation?", o: ["The findings represent the organisation because the respondents work there.", "The findings are indicative of this unit but may not represent the wider organisation.", "The findings represent all production employees because participation was voluntary.", "The findings are unreliable because questionnaires cannot support business decisions."], a: 1, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "You are translating a producer’s instruction into formal English: “Если разрешение не будет получено к понедельнику, съёмки придётся перенести.”", o: ["If the permit was not received at Monday, filming has to be rescheduled yesterday.", "Unless the permit is obtaining on Monday, the filming would have postponed.", "If the permit is not obtained by Monday, the filming will have to be postponed.", "If the permit will not obtain until Monday, filming must postponing."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are writing a recommendation after finding that editors lose time searching for current scripts in different folders. Which recommendation is specific, action-oriented, and logically connected to the finding?", o: ["Editors should be more organised and try to search for scripts carefully.", "The report recommends that all editing work should stop until every folder is reorganised.", "The company might perhaps consider improving its general approach to file management.", "Create one controlled project folder and require editors to use the approved version."], a: 3, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are responding to an international client who writes, “Please revert with the final schedule.” In this context, which reply uses the word correctly in standard international business English?", o: ["We will revert the final schedule by 4 p.m. tomorrow.", "We will return you the final schedule by 4 p.m. tomorrow.", "We will revert back to you with the final schedule by tomorrow.", "We will reply with the final schedule by 4 p.m. tomorrow."], a: 3, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "You are chairing a meeting in which two departments present conflicting figures for post-production costs. What should you do first if the goal is an evidence-based decision?", o: ["Average the figures immediately so that the disagreement does not delay the meeting.", "Accept the finance department’s figures because its title gives it automatic authority.", "Select the lower figure because it offers the organisation the more attractive outcome.", "Clarify the definitions, sources, and reporting periods behind both figures."], a: 3, h: "Aim for respectful participation, clarification, objective discussion, and a clearly recorded outcome." },
  { q: "You are preparing a business report after interviewing editors about repeated overtime. Several participants mention unclear approval procedures, but you have not independently verified the claim. Which sentence reports the evidence most responsibly?", o: ["Unclear procedures were definitely responsible for the department’s overtime.", "The department’s overtime resulted from editors’ unwillingness to work efficiently.", "Interviewees frequently attributed overtime to unclear approval procedures.", "The interviews prove that unclear procedures caused all overtime."], a: 2, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are translating a producer’s instruction into formal English: “Не распространяйте предварительный монтаж до получения письменного разрешения.”", o: ["Do not distribute the rough cut before written approval will be received.", "Do not disseminate the preliminary editing before receiving an approval writing.", "Do not spread the first montage until you receive written permission.", "Do not distribute the rough cut until written approval has been received."], a: 3, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are writing to a client whose requested soundtrack cannot be licensed for the planned release. Which sentence states the problem tactfully and offers a practical alternative?", o: ["The soundtrack cannot be used, and no alternative can be guaranteed.", "Your chosen track is unsuitable for this project, so the music must be replaced with a new selection immediately.", "We cannot use your soundtrack because the request was made too late.", "The requested track is unavailable for this release, but we can propose two licensed alternatives."], a: 3, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "You are checking a production email before sending it: “The director suggested to postpone the screening because the subtitles were not completed.” Which revision uses the correct verb pattern?", o: ["The director suggested postpone the screening because the subtitles were not completing.", "The director suggested postponing the screening because the subtitles were incomplete.", "The director suggested that postponing the screening because the subtitles did not complete.", "The director suggested to postponing the screening because subtitles had not completed."], a: 1, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "You are reviewing a proposal for an online film archive. The proposal promises increased access but provides no user data, cost estimates, implementation schedule, or risk analysis. What is the most appropriate professional response?", o: ["Recommend immediate approval because improved access is automatically financially sustainable.", "Request evidence, a budget, a timetable, and a risk assessment before recommending approval.", "Approve the proposal provisionally without conditions because further evidence may discourage innovation.", "Reject the proposal because online archives cannot replace physical film collections."], a: 1, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "Translate into formal business English: “Поскольку исходные файлы были повреждены, команда запросила дополнительный день для завершения монтажа.”", o: ["Since the original files have damaged, the team demanded an extra day for completing the montage.", "As the initial files had been corrupted, the team requested an additional day for the editing to be completed by them.", "Because the source files were corrupted, the team requested an additional day to complete the editing.", "Because the source files were damaging, the team requested one day additionally to finish edit."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "Choose the grammatically correct completion: “The revised production schedule, together with the location permits, ___ to the client yesterday.”", o: ["were sending", "have been sent", "were sent", "was sent"], a: 3, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A report finds that staff received safety training, but observation records show that protective equipment was still used inconsistently. Which conclusion is most logically justified?", o: ["The observation records prove that staff rejected all safety procedures.", "Training occurred, but its effect on consistent equipment use remains limited or uncertain.", "The training failed because no employee used protective equipment correctly.", "Safety training was unnecessary because equipment use depends only on supervision."], a: 1, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Translate into accurate formal English: “Мы не можем утвердить смету до тех пор, пока не получим подтверждение финансирования.”", o: ["We cannot approve the budget until we receive confirmation of funding.", "We cannot approve the estimate unless we will receive funding confirmation.", "We cannot approve the budget since we received confirmation of funding.", "We are unable approving the budget until the financing has confirmed."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "Select the best revision for clarity, concision, and active voice: “A decision regarding the postponement of the launch will be made by the executive committee after a review of the findings.”", o: ["After a review of the findings, the postponement of the launch will receive a decision.", "A decision on the launch postponement will be made by the committee after findings are reviewed.", "The executive committee will undertake a decision regarding postponing the launch after the findings’ review.", "The executive committee will decide whether to postpone the launch after reviewing the findings."], a: 3, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "Translate into formal English: “Несмотря на задержку разрешения, съёмочная группа завершила подготовку к началу съёмок.”", o: ["Despite of the delayed permit, the production crew completed the preparation of filming.", "Despite the delay in obtaining the permit, the production crew completed preparations for filming.", "In spite the permission delay, the filming team finished the preparations for shoot.", "Although the permit delayed, the production crew has completed preparing to begin filming."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "Choose the correct completion: “If the broadcaster ___ the contract today, the legal team will review it tomorrow.”", o: ["has sign", "signs", "signed", "will sign"], a: 1, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "A report shows that a new editing workflow reduced average processing time from six days to four, but it also increased training costs. Which conclusion is most defensible?", o: ["The workflow is successful because faster processing always outweighs higher costs.", "The workflow improved processing speed, although its overall value requires cost-benefit assessment.", "The workflow failed because any increase in training costs invalidates operational benefits.", "The workflow caused the improvement because the report proves that no other factor mattered."], a: 1, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Translate into formal English: “Просим вас не включать конфиденциальные материалы в общую рассылку.”", o: ["We request you do not include the confidential materials into the common sending.", "Please avoid to include confidential materials in the overall distribution.", "Kindly do not include confidential materials on the general mail.", "Please do not include confidential materials in the general circulation."], a: 3, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "Choose the best revision for a professional report: “The findings are very important and clearly show that employees really need more training.”", o: ["The findings really show that more training is needed by employees in the organisation.", "The findings indicate a significant need for additional employee training.", "The findings are important and show employees have a need of additional trainings.", "The findings clearly prove that employees desperately need much more training."], a: 1, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "A documentary team finds that interviewees give conflicting accounts of a production delay. Which report-writing response best protects accuracy and fairness?", o: ["Select the most detailed account and present it as the established cause", "Attribute the delay to the department with the weakest institutional authority", "Present the differing accounts, identify corroborating evidence, and state the limitation", "Combine the accounts into one narrative without identifying the disagreement"], a: 2, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "Translate into formal business English: “Хотя бюджет был утверждён, расходы следует контролировать еженедельно.”", o: ["Although the budget was approving, expenditure should be controlled on weekly basis.", "Even the budget has approved, the expenses are monitoring weekly.", "Although the budget has been approved, expenditure should be monitored weekly.", "Despite the budget approved, expenses must control every weeks."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "Choose the correct completion: “Neither the revised script nor the production notes ___ attached to the email.”", o: ["were", "has been", "was", "is"], a: 0, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "A film company’s report recommends adopting a digital archive, but the evidence covers only short-term storage costs and excludes staff training, migration risks, and long-term maintenance. What is the strongest analytical response?", o: ["Qualify the recommendation and request a full lifecycle cost and risk assessment", "Approve the archive because short-term savings establish overall feasibility", "Reject the archive because incomplete evidence makes every digital system unsuitable", "Treat staff training and migration risks as operational details outside the report’s scope"], a: 0, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "A production report finds that a new editing system reduced turnaround time, but the study used only six projects from one department and did not measure training costs. Which recommendation is most defensible?", o: ["Conduct a broader cost-benefit assessment before adopting the system organisation-wide", "Adopt the system immediately because shorter turnaround proves overall efficiency", "Reject the system because a small sample cannot support any useful conclusion", "Claim that the system caused all improvements because no alternative explanation is needed"], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Translate into formal English: “Если клиент не подтвердит расписание до пятницы, съёмки будут перенесены.”", o: ["If the client does not confirm the schedule at Friday, filming has postponed.", "If the client will not confirm the timetable until Friday, filming is postponing.", "If the client does not confirm the schedule by Friday, filming will be postponed.", "Unless the client confirmed the schedule on Friday, filming would be postponed."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A production manager is revising a report after discovering that interviewees used “quality” to mean different things. Which methodological revision best improves the report’s validity?", o: ["Treat every use of “quality” as equivalent because it reflects participant experience", "Define quality operationally and analyse responses against the same criteria", "Remove contradictory responses to produce a clearer overall conclusion", "Replace the interview data with the manager’s professional judgement"], a: 1, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Translate into formal English: “Несмотря на ограниченные данные, результаты указывают на необходимость дальнейшего исследования.”", o: ["Despite of limited data, the results are pointing the necessity for researching again.", "Despite the limited data, the results indicate the need for further research.", "In spite the limited informations, the results indicate to further researches.", "Although the data is restricted, the results prove further research is necessary."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A report states: “The new workflow improved productivity because employees completed more tasks during the pilot.” Which revision demonstrates stronger critical reasoning?", o: ["The pilot confirms that productivity can be measured adequately by task numbers alone.", "While task completion increased, claiming the workflow is effective in every department is an overgeneralization of the pilot data.", "The pilot recorded higher task completion, but other factors should be examined before attributing the improvement solely to the workflow.", "The workflow caused higher productivity because task completion increased during the pilot."], a: 2, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "Choose the correct completion: “The producer recommended that the final cut ___ reviewed by legal counsel before distribution.”", o: ["is", "be", "being", "was"], a: 1, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "A documentary producer is translating a funding agreement into a report. The original states: “Финансирование предоставляется при условии, что проект будет завершён до 30 июня.” Which translation preserves the conditional relationship and formal register?", o: ["Funding will provide the project if it completes until 30 June.", "Funding is available despite the project being completed after 30 June.", "Funding will be provided on the condition that the project is completed by 30 June.", "Funding was provided because the project had been completed before 30 June."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A final-year student writes: “The survey was administered to editors who had completed the pilot, and their responses were compared with those of editors who had not.” Why is the past perfect form had completed appropriate in this sentence?", o: ["It replaces the passive form required for research methods.", "It marks completion before the later comparison or survey-related past event.", "It describes an action that was ongoing or continuing into the present moment.", "It expresses a future condition in a past narrative."], a: 1, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "A multimedia company’s report concludes that a new streaming campaign increased engagement because views rose during the campaign. However, a major film festival occurred at the same time. Which revision best demonstrates critical interpretation of evidence?", o: ["Engagement increased during the campaign, but the festival may also have contributed to the rise.", "The campaign definitely caused the increase because its timing preceded the higher views.", "The increase proves that the campaign would produce the same result in every market.", "The festival should be ignored because the campaign was the company’s intended intervention."], a: 0, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "Translate into precise formal English: “Перед публикацией отчёта редактор должен проверить все цитаты и убедиться, что источники указаны в соответствии со стилем APA.”", o: ["Before publishing the report, the editor must check all quotations and ensure that the sources are cited in accordance with APA style.", "Before the publication of report, the editor must verify quotations and confirm sources are written with APA style.", "Before the report is published, the editor must check every quote and ensure that all sources are indicated by using the APA style.", "Before publishing the report, the editor should ensure all citations are according to the APA’s references."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A production team is writing an internal memo about a failed data backup. Which sentence best uses modality to distinguish an immediate obligation from a recommended preventive measure?", o: ["The team has restored the files today and tested the backup system weekly.", "The team must restore the files today and should test the backup system weekly.", "The team may restore the files today and can test the backup system weekly.", "The team should restore the files today and must test the backup system weekly."], a: 1, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "A documentary producer is revising a report after discovering that the questionnaire measured “audience satisfaction” with a single undefined question. Which revision most improves construct validity without overstating the evidence?", o: ["Remove dissatisfied responses because they conflict with the project’s expected outcome", "Replace the questionnaire with the producer’s personal assessment of audience reactions", "Treat a single positive response as sufficient evidence of overall satisfaction", "Define satisfaction through several relevant indicators and explain how responses will be interpreted"], a: 3, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "Translate into formal English: “До утверждения окончательного монтажа режиссёр должен проверить, соответствуют ли субтитры утверждённому сценарию.”", o: ["Before the final editing approves, the director must check if subtitles are corresponding with the approving script.", "Before approving the final cut, the director must check whether the subtitles correspond to the approved script.", "Before approval of the final montage, the director must check whether subtitles are agreed by the script.", "Until the final cut is approved, the director should check that subtitles corresponded to the script."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A production report states: “Because the sample contained only final-year Film and Multimedia students from one university, the findings cannot automatically be generalised to all media students.” What is the main reasoning expressed by because?", o: ["It introduces a recommendation for expanding the sample.", "It reports a consequence that occurred after generalisation.", "It introduces the methodological reason for limiting generalisation.", "It contrasts the sample with an unrelated population."], a: 2, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "Complete the sentence with the most appropriate tense and aspect: “By the time the broadcaster requested the master file, the post-production team ___ the required technical specifications.”", o: ["was already confirming", "had already confirmed", "has already confirmed", "already confirms"], a: 1, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "A film company is rejecting a proposal to release an unfinished documentary but wants to preserve the applicant’s goodwill. Which paragraph best applies an indirect negative-message structure?", o: ["We appreciate the strength of the concept. However, the current cut does not yet meet the technical requirements for release. We would welcome a revised submission after the missing sound and rights documentation have been completed.", "Your documentary is unfinished, so we cannot release it. Submit it again when you have corrected everything.", "The proposal cannot be accepted, and further correspondence about the project will not be considered.", "While we recognize the creative potential within your documentary concept, the current version lacks the necessary technical elements required for our release standards. We would be happy to review a new proposal once the project is complete."], a: 0, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "A film-production company has received conflicting audience data from a questionnaire and focus-group interviews about a proposed streaming service. As a final-year multimedia researcher, which report-writing approach best demonstrates methodological rigour?", o: ["Define each measure, compare the methods, explain the divergence, and limit conclusions to the evidence", "Average the findings and present one definitive result without discussing methodological differences", "Remove contradictory responses so that the report communicates a clear organisational position", "Prefer the focus-group data because qualitative evidence is always more reliable than questionnaires"], a: 0, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "Translate into formal English: “Если результаты пилотного исследования подтвердятся, компания расширит программу обучения на все производственные отделы.”", o: ["Unless the pilot results confirm, the company will extend training to every production department.", "If the results were confirming, the company would have extended the training programme to all departments.", "If the pilot-study results are confirmed, the company will extend the training programme to all production departments.", "If the pilot results will confirm, the company extends the training programme for every production department."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A director writes in a production memo: “The revised schedule is more feasible than the original one, because it allocates additional time for colour grading.” Which revision best preserves the comparative meaning and improves cohesion?", o: ["The revised schedule is more feasibly than the original because additional time is allocating.", "The revised schedule is most feasible than the original one because it gives time for colour grading.", "The revised schedule is more feasible than the original because it allows additional time for colour grading.", "The revised schedule is feasible compared to the original, although it allocates less time for colour grading."], a: 2, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "A final-year student is writing a critical report on a film campaign. The campaign’s online views increased after a celebrity endorsement, but the report has no control group and does not measure prior audience loyalty. Which conclusion is most academically defensible?", o: ["The campaign was successful for all target audiences because the overall view count increased significantly during the period.", "The endorsement was ineffective because online views cannot measure campaign success.", "The increase coincided with the endorsement, but its independent effect cannot be established from the available evidence.", "The endorsement caused the increase because the timing establishes a direct causal relationship."], a: 2, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Translate into formal English: “Хотя продюсер одобрил концепцию, окончательное решение будет принято после рассмотрения сметы и анализа рисков.”", o: ["Although the producer approved the concept, the final decision will be made after the budget and risk analysis have been reviewed.", "Although the producer has approved the concept, the final decision is making after reviewing the budget and risks.", "Despite the producer approved the concept, the final decision will make after the budget and the risk analysis have been reviewed.", "Although the producer approved the concept, the final decision was made before the budget and risk analysis were considered."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A final-year multimedia researcher is analysing interviews about the effect of short-form video on documentary engagement. Several participants use “engagement” to mean viewing duration, while others mean commenting and sharing. Which revision best improves the study’s conceptual precision and supports a defensible report?", o: ["Adopt the most frequent definition and treat all other participant responses as irrelevant to the study", "Define engagement as separate measurable dimensions, explain the coding scheme, and interpret each dimension independently", "Replace the participants’ meanings with the researcher’s preferred definition after data collection", "Combine viewing, commenting, and sharing into one score without defining the construct"], a: 1, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "Translate into formal business English: “После того как права на музыку будут подтверждены, редактор включит окончательный саундтрек в мастер-файл.”", o: ["Once the music rights have been confirmed, the editor will incorporate the final soundtrack into the master file.", "After confirming the music rights, the final soundtrack will be incorporated into the master file by the editor.", "When the music rights confirmed, the editor will include finally the soundtrack on the master file.", "After the music rights will confirm, the editor incorporates the final soundtrack in the master file."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "A production manager writes: “The team completed the reshoot despite the location manager had withdrawn permission.” Select the revision that correctly expresses the relationship between the two past events.", o: ["The team completed the reshoot although the location manager withdrawing permission.", "The team completed the reshoot despite the location manager withdrew permission.", "The team completed the reshoot despite the location manager’s having withdrawn permission.", "The team had completed the reshoot despite the location manager has withdrawn permission."], a: 2, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "A report compares two film-distribution strategies. Strategy X generated more views, but Strategy Y produced higher completion rates and more paid subscriptions. Which conclusion best demonstrates appropriate interpretation rather than reliance on a single metric?", o: ["Strategy X maximised reach, whereas Strategy Y produced stronger evidence of sustained and monetised engagement.", "Both strategies were equally effective because they generated audience activity.", "Strategy Y failed because its total views were lower than Strategy X’s.", "Strategy X was superior because total views represent the most critical metric for measuring overall audience reach."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Translate into precise formal English: “Не следует делать окончательные выводы на основании результатов одного отдела без проверки их применимости к другим подразделениям.”", o: ["Definitive conclusions must not be drawn because departmental results can never be applied to other units or different divisions.", "Definitive conclusions should not be drawn from one department’s results without testing their applicability to other units.", "Final conclusions should not make from the results of one department before applying them to other departments.", "We should not conclude finally on one department results unless other units have been tested by it."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are preparing a report on a campus film festival. Attendance increased after free transport was introduced, but the festival also received national media coverage. Which conclusion best reflects critical analysis?", o: ["Attendance increased after the intervention, but media coverage may also have contributed.", "The intervention failed because attendance cannot be attributed to one factor.", "National media coverage had no effect because it was not part of the intervention.", "The introduction of free transport was the sole cause of the increase in attendance."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are translating a director’s instruction into formal English: “До начала съёмок убедитесь, что все участники подписали формы согласия.”", o: ["Before filming will begin, ensure all participants signed the consent forms.", "Before filming begins, ensure that all participants have signed the consent forms.", "Before the film starts, ensure the consent forms have signed all participants.", "Before beginning the shooting, confirm that all participants are signing the consent forms."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are writing an internal memo after a data breach. The investigation is incomplete, and the company wants to avoid speculation. Which sentence is most appropriate?", o: ["Everyone should stop discussing the incident until management identifies the person responsible.", "The incident probably resulted from an external attack, although this remains uncertain.", "The incident is under investigation; staff should not circulate unverified information.", "The breach was caused by the editing team’s careless password practices."], a: 2, h: "Consider the reader, the purpose, the appropriate level of formality, and the action the message needs to communicate." },
  { q: "You are translating this client message into formal English: “Мы были бы признательны, если бы вы могли предоставить подробную смету к четвергу.”", o: ["We are grateful that you could provide the budget in details on Thursday.", "We would be appreciating you to submit a detailed costing before Thursday.", "We would appreciate it if you could provide a detailed budget by Thursday.", "We will appreciate if you can provide the detailed estimate until Thursday."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are reviewing a proposal for an interactive documentary. The proposal offers strong creative ideas but does not explain accessibility, data protection, or audience evaluation. What is the most defensible response?", o: ["Approve the proposal immediately, as creative quality is more important than operational details.", "Recommend immediate production and add accessibility and privacy measures after launch.", "Request an implementation plan addressing accessibility, data protection, and evaluation before approval.", "Reject the proposal because interactive documentaries cannot be evaluated objectively."], a: 2, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "You are translating a post-production memo: “Если резервная копия не будет проверена сегодня, команда может потерять доступ к исходным материалам.” Which version is grammatically and professionally accurate?", o: ["If the backup will not be tested today, the team may lose the access to source materials.", "If the backup is not tested today, the team may lose access to the source materials.", "Unless the backup is not checked today, the team can lose access for the original materials.", "If the backup was not tested today, the team might have lost access to the source materials."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are reviewing a report whose survey respondents were recruited through the company’s social-media page. Most respondents were already followers of the company. Which interpretation is most methodologically responsible?", o: ["The respondents’ existing interest proves that the company’s content caused their loyalty.", "The results are invalid because online questionnaires cannot produce useful evidence.", "The sample is representative because social-media followers reflect the general audience.", "The sample may overrepresent people already interested in the company’s content."], a: 3, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "You are writing a formal email to a broadcaster. Complete the sentence correctly: “We look forward to ___ your comments on the revised documentary.”", o: ["receive", "received", "have received", "receiving"], a: 3, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are translating a client’s request into formal English: “Пожалуйста, сообщите нам, были ли все необходимые разрешения получены до начала съёмок.”", o: ["Please inform us if all necessary permissions have obtained before filming begins.", "Please report whether all necessary permits were obtaining before filming had begun.", "Please let us know whether all the required permits had been obtained before filming began.", "Kindly tell us were all the required permits received before the filming has begun."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are analysing a report that claims a new editing software caused productivity to rise because output increased during its trial. However, the trial also involved extra staff and shorter projects. Which critique is strongest?", o: ["The evidence does not isolate the software’s effect from other changes during the trial.", "The software caused the increase because productivity rose while it was being used.", "The claim is false because productivity cannot be measured through output.", "The extra staff and shorter projects are irrelevant because the software was the main intervention."], a: 0, h: "Match the strength of the conclusion to the size, quality, and limits of the evidence provided." },
  { q: "You are writing a report on a campus film festival. Attendance rose after free transport was introduced, but the festival also changed its advertising strategy and moved to a larger venue. Which conclusion is most defensible?", o: ["Attendance increased during the intervention, but the separate effects of transport, advertising, and venue cannot be isolated.", "The larger venue caused the increase because it allowed more people to attend.", "Free transport was the primary driver of the increase because it was the most visible change implemented during the festival period.", "The advertising strategy had no effect because transport was free."], a: 0, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Translate into formal English: “До публикации фильма необходимо убедиться, что все участники подписали формы согласия.”", o: ["Before the film is published, all participants must ensure that they have signed the necessary consent forms.", "Until the film publishes, ensure all participants are signing consent forms.", "Before the film is published, it is necessary to ensure that all participants have signed the consent forms.", "Before the publication of film, it is necessary ensuring participants signed the consents."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are revising this sentence in a feasibility report: “The project is likely to be profitable because many students said that they liked the idea.” Which revision uses evidence more cautiously?", o: ["Student approval proves that the project will be profitable.", "The project is profitable because most respondents liked the idea.", "Profitability cannot be guaranteed solely on the basis of student opinions, as financial data is still required.", "The positive responses indicate potential demand, but profitability also depends on costs and revenue projections."], a: 3, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "Complete the sentence in a formal email: “The revised budget, together with the supporting quotations, ___ attached for your review.”", o: ["is", "have", "are", "were"], a: 0, h: "Check subject–verb agreement, verb form, tense consistency, and the grammatical pattern required by the sentence." },
  { q: "You are translating a client’s complaint into a professional response: “Мы понимаем ваше беспокойство, но не можем вернуть деньги до завершения проверки.” Which version best preserves the meaning and tone?", o: ["We understand your concern, but you will not receive money until we decide what happened.", "We understand your worry, although we cannot return money before checking everything.", "We understand your concern, but we cannot issue a refund until the investigation is complete.", "We acknowledge your complaint, but refunds are impossible because the investigation has started."], a: 2, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are translating a production manager’s instruction into formal English: “Если исходные материалы не будут проверены сегодня, монтаж может быть отложен.” Which translation preserves the conditional meaning and professional register?", o: ["If the source materials are not checked today, the editing may be delayed.", "If the source materials will not be checked today, the editing may delay.", "If the source materials were not checked today, the editing is delaying.", "Unless the source materials are checked today, the editing has delayed."], a: 0, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are analysing a report on a new editing workflow. Turnaround time fell from six days to four, but the study included only three projects and did not measure overtime. Which conclusion is most defensible?", o: ["The workflow failed because overtime was not measured.", "The workflow has proved universally efficient.", "The workflow caused the improvement beyond any reasonable doubt.", "The workflow appears promising, but its wider efficiency requires further evidence."], a: 3, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." },
  { q: "You are writing to a broadcaster after receiving an incomplete contract. Choose the sentence with the clearest professional request.", o: ["Please send the missing licensing schedule so that we can complete our review.", "Please revert back the licensing schedule at your earliest convenience.", "Send us the missing thing before we can do the needful.", "Kindly send the schedule which is missing for our perusal."], a: 0, h: "Choose the option that is clear, accurate, professional, and directly supported by the situation described." },
  { q: "You are translating this formal report sentence into English: “Хотя большинство участников поддержало проект, результаты нельзя обобщать на всех студентов университета.”", o: ["Despite most participants support the project, the results must not generalise to every student.", "Although most participants supported the project, the findings cannot be generalised to all university students.", "Although the majority supported the project, the findings cannot generalise all university students.", "Although most participants had supported the project, the findings cannot be generalised for all students."], a: 1, h: "Focus on preserving the original meaning while using standard grammar, clear wording, and a professional register." },
  { q: "You are reviewing a proposal for a campus streaming platform. Students express strong interest, but the proposal provides no cost estimates, privacy safeguards, or maintenance plan. What should your recommendation say?", o: ["Reject the proposal because online platforms are inherently risky.", "Request financial, privacy, and maintenance details before approval.", "Approve the platform because student interest guarantees viability.", "Approve it provisionally without conditions and address the gaps after launch."], a: 1, h: "A strong report is objective, evidence-based, precise, and careful not to claim more than the data supports." }
];
